function politicalGaugeIndex(label){
  const normalizedLabel = POLITICAL_METER_GROUPS[label] || label;
  const idx = POLITICAL_METER_ORDER.indexOf(normalizedLabel);
  return idx < 0 ? 6 : idx;
}

function politicalGaugeHtml(name){
  const current = POLITICAL_METER[name] || {label:'Positionnement à préciser'};
  const displayedLabel = POLITICAL_METER_DISPLAY[POLITICAL_METER_GROUPS[current.label] || current.label] || POLITICAL_METER_GROUPS[current.label] || current.label;
  const index = politicalGaugeIndex(current.label);
  const segments = POLITICAL_METER_ORDER.length;

  const colorByLabel = {
    'Humanisme':'#a06ad8',
    'Antilibéralisme':'#a96bd2',
    'Communiste':'#d75a62',
    'Socialisme':'#e56b73',
    'Ecologiste':'#61b879',
    'Animalisme':'#83c98f',
    'Social-Libéralisme':'#d8b963',
    'Européisme':'#e2c96d',
    'Monarchisme':'#d8d4cb',
    'Mondialisme':'#d6ba63',
    'Euroscepticisme':'#cda84d',
    'Souverainisme':'#69afd6',
    'Libéralisme':'#5ba8d4',
    'Traditionalisme':'#5e86bc',
    'Patriotisme':'#4b76ae',
    'Conservatisme':'#37629a',
    'Nationalisme':'#294f84'
  };

  const zoneFor = (label) => {
    if (POLITICAL_METER_LABELS.left.includes(label)) return 'left';
    if (POLITICAL_METER_LABELS.center.includes(label) || label === 'Monarchisme') return 'center';
    return 'right';
  };

  const segmentHtml = POLITICAL_METER_ORDER.map((label,i)=>{
    const active = i===index ? ' is-active' : '';
    const zone = zoneFor(label);
    const color = colorByLabel[label] || '#737b86';
    const cursor = i===index ? '<span class="political-spectrum-cursor" aria-hidden="true"></span>' : '';
    return `<span class="political-spectrum-segment ${zone}${active}" style="--seg:${color}" aria-label="${safeText(label)}" title="${safeText(label)}"><span>${safeText(label)}</span>${cursor}</span>`;
  }).join('');

  const progress = segments > 1 ? (index/(segments-1)) : 0.5;
  const groupColor = colorByLabel[displayedLabel] || colorByLabel[current.label] || '#b58a4b';
  const displayName = POLITICAL_METER_DISPLAY[current.label] || current.label;
  const normalizedLabel = POLITICAL_METER_GROUPS[current.label] || current.label;
  const activeIndex = politicalGaugeIndex(current.label);
  const activeZone = zoneFor(normalizedLabel);

  return `<section class="political-meter political-meter-modern" aria-label="Baromètre indicatif du positionnement politique de ${safeText(name)}">
    <div class="political-meter-modern-head">
      <div>
        <span class="section-kicker">POSITIONNEMENT POLITIQUE</span>
        <h4>Repère idéologique</h4>
        <p class="political-meter-subtitle">Le curseur se place sur le courant principal retenu pour cette personnalité.</p>
      </div>
      <div class="political-meter-current-wrap modern-current" style="--current-color:${groupColor}" aria-label="Courant retenu : ${safeText(displayName)}">
        <span class="political-meter-current-dot"></span>
        <strong class="political-meter-current">${safeText(displayName)}</strong>
      </div>
    </div>

    <div class="political-spectrum" data-active-index="${activeIndex}" data-active-zone="${activeZone}" style="--meter-progress:${progress}%;--current-color:${groupColor}">
      <div class="political-spectrum-track" role="list" aria-label="Échelle indicative des courants politiques">
        ${segmentHtml}
      </div>
    </div>

    <div class="political-gauge-principal political-gauge-principal-modern">
      <span class="political-gauge-principal-kicker">COURANT RETENU</span>
      <span class="political-gauge-principal-value" style="--current-color:${groupColor}">${safeText(displayName)}</span>
    </div>
    <p class="political-meter-note">Repère éditorial indicatif : la position matérialisée correspond au courant principal associé à cette fiche. Ce repère ne constitue ni un score scientifique ni une mesure absolue.</p>
  </section>`;
}

const POLITICAL_POSITION_GUIDE = {
  'Humanisme':'Courant plaçant la dignité de la personne humaine, les libertés fondamentales, l’épanouissement individuel et la responsabilité collective au cœur de la réflexion politique.',
  'Antilibéralisme':'Critique de la primauté accordée aux mécanismes libéraux, notamment lorsqu’ils sont considérés comme incompatibles avec l’égalité sociale, la souveraineté ou l’autorité politique.',
  'Communisme':'Tradition politique qui met l’accent sur l’appropriation collective des moyens de production, la lutte contre les rapports de classe et une transformation profonde de l’ordre économique.',
  'Socialisme':'Courant attaché à la réduction des inégalités, à la protection sociale, aux services publics et à une intervention importante de la puissance publique dans l’économie.',
  'Ecologisme':'Courant qui place les limites écologiques, la transformation des modes de production et de consommation et la protection des écosystèmes au cœur du projet politique.',
  'Animalisme':'Courant qui élargit la réflexion politique au statut, à la protection et à la condition des animaux, avec des conséquences sur l’agriculture, l’alimentation et les pratiques économiques.',
  'Social-Libéralisme':'Position cherchant à associer économie de marché, protections sociales, droits individuels et intervention publique ciblée pour corriger les déséquilibres.',
  'Européisme':'Orientation favorable à la construction européenne et à une intégration importante des États membres dans des politiques communes.',
  'Orléanisme':'Tradition monarchique constitutionnelle issue de la branche d’Orléans, historiquement associée au parlementarisme, aux libertés publiques et à une monarchie représentative.',
  'Légitimisme':'Tradition monarchique attachée à la branche aînée des Bourbons et à une conception héréditaire de la légitimité dynastique.',
  'Bonapartisme':'Tradition politique valorisant un exécutif fort, l’appel direct au peuple et la souveraineté nationale, dans la continuité de l’héritage napoléonien.',
  'Mondialisme':'Terme utilisé pour désigner une orientation favorable à une coopération internationale poussée et à des institutions ou normes dépassant le cadre strictement national.',
  'Euroscepticisme':'Orientation critique à l’égard du degré d’intégration européenne, de certaines compétences de l’Union ou de leurs effets sur la souveraineté nationale.',
  'Souverainisme':'Courant donnant la priorité à la capacité de la nation à décider de ses règles, de ses frontières, de son budget et de ses choix diplomatiques.',
  'Libéralisme':'Courant mettant en avant les libertés individuelles, l’État de droit, l’initiative privée et, selon les sensibilités, une économie de marché plus ou moins régulée.',
  'Traditionalisme':'Orientation privilégiant la continuité culturelle, historique et sociale, la transmission des normes héritées et la stabilité des institutions.',
  'Patriotisme':'Attachement politique à la nation et à la continuité de la communauté nationale, pouvant se combiner avec différentes conceptions de la République et de l’État.',
  'Conservatisme':'Courant mettant l’accent sur l’ordre, la continuité des institutions, la prudence face aux ruptures et la préservation de cadres sociaux ou culturels jugés structurants.',
  'Nationalisme':'Courant plaçant la nation au centre de la légitimité politique et accordant une importance particulière à l’indépendance, à l’identité collective et à la puissance nationale.'
};

