function injectPortrait(el, path, alt){
  if (el.querySelector('.ruler-portrait,.joint-portraits')) return;
  const img=document.createElement('img');
  img.className='ruler-portrait';
  img.src=path;
  img.alt=alt;
  img.loading='lazy';
  img.decoding='async';
  el.prepend(img);
}
for (const el of document.querySelectorAll('[data-ruler]')) {
  const name=el.dataset.ruler;
  const d=D[name];
  if (el.querySelector('.ruler-portrait,.joint-portraits')) continue;
  if (d?.portraits?.length){
    const wrap=document.createElement('div');
    wrap.className='joint-portraits';
    d.portraits.forEach((path,i)=>{
      const img=document.createElement('img');
      img.className='ruler-portrait joint';
      img.src=path;
      img.alt=`Portrait de ${i===0?'Louis III':'Carloman II'}`;
      img.loading='lazy';
      img.decoding='async';
      wrap.appendChild(img);
    });
    el.prepend(wrap);
  } else if(d?.portrait) {
    injectPortrait(el,d.portrait,`Portrait de ${d.title}`);
  }
}

function describePin(name, d){
  const dynasty = (d?.type || '').replace(/^Souverain\s*·\s*/, '');
  const date = d?.reign || d?.dates || 'Dates non précisées';
  let desc = d?.history || 'Notice encyclopédique à compléter.';
  desc = desc.replace(/\s+/g,' ').trim();
  if (desc.length > 150) desc = desc.slice(0, 147).replace(/[ ,;:.!?]+$/,'') + '…';
  return {dynasty: dynasty || 'Histoire de France', date, desc};
}

/* LYS V24 — proximité des épingles : calcul uniquement lors d’un mouvement réel du pointeur.
   Le scroll ne relance plus la mesure de toutes les épingles : cela évite les clignotements et le lag. */
(function initRulerProximity(){
  const pins=[...document.querySelectorAll('[data-ruler]')];
  if(!pins.length || !window.matchMedia('(pointer:fine)').matches) return;

  const tooltip=document.createElement('div');
  tooltip.id='ruler-proximity-tooltip';
  tooltip.setAttribute('aria-hidden','true');
  document.body.appendChild(tooltip);

  let raf=0, mouseX=-9999, mouseY=-9999;
  const radius=180;

  function update(){
    raf=0;
    let nearest=null;
    let nearestDistance=Infinity;

    for(const pin of pins){
      const r=pin.getBoundingClientRect();
      const cx=r.left+r.width/2;
      const cy=r.top+r.height/2;
      const d=Math.hypot(mouseX-cx, mouseY-cy);
      const near=d <= radius;
      pin.classList.toggle('pin-near', near);
      if(near && d<nearestDistance){
        nearest=pin;
        nearestDistance=d;
      }
    }

    if(nearest){
      tooltip.textContent=nearest.dataset.ruler || '';
      tooltip.classList.add('is-visible');
      const tr=nearest.getBoundingClientRect();
      const left=Math.min(Math.max(tr.left + tr.width/2, 110), window.innerWidth-110);
      const top=Math.max(14, tr.top-18);
      tooltip.style.left=`${left}px`;
      tooltip.style.top=`${top}px`;
    }else{
      tooltip.classList.remove('is-visible');
    }
  }

  const request=()=>{ if(!raf) raf=requestAnimationFrame(update); };
  const clearDuringLayoutChange=()=>{
    if(raf) cancelAnimationFrame(raf);
    raf=0;
    for(const pin of pins) pin.classList.remove('pin-near');
    tooltip.classList.remove('is-visible');
  };
  const move=e=>{
    if (typeof e.clientX !== 'number' || typeof e.clientY !== 'number') return;
    mouseX=e.clientX;
    mouseY=e.clientY;
    request();
  };
  document.addEventListener('pointermove',move,{passive:true});
  window.addEventListener('scroll',clearDuringLayoutChange,{passive:true});
  window.addEventListener('resize',clearDuringLayoutChange,{passive:true});
})();

function decorateRulerPins(){
  document.querySelectorAll('[data-ruler]').forEach(el=>{
    const name=el.dataset.ruler;
    const d=D[name];
    if(!d || el.querySelector('.pin-copy')) return;
    const meta=describePin(name,d);
    const copy=document.createElement('span');
    copy.className='pin-copy';
    const badgeMap = {
      'Mérovingiens':'merovingiens.png','Carolingiens':'carolingiens.png','Capétiens':'capetiens.png','Valois':'valois.png','Valois-Orléans':'valois-orleans.png','Valois-Angoulême':'valois-angouleme.png','Bourbons':'bourbons.png','Orléans':'orleans.png','Bonaparte':'bonaparte.png','Robertiens':'bourgogne.png','Bosonides / Bourgogne':'bourgogne.png','Bourgogne':'bourgogne.png','Anjou':'anjou.png','Flandre':'flandre.png','Normandie':'normandie.png','Plantagenêt':'plantagenet.png','Blois':'blois.png','Boulogne':'boulogne.png','Hauteville':'hauteville.png','Vermandois':'vermandois.png'
    };
    const badgeKey = Object.keys(badgeMap).find(k => meta.dynasty.includes(k));
    const badgeHtml = badgeKey ? `<span class="pin-dynasty-badge"><img src="assets/dynasties/${badgeMap[badgeKey]}" alt="Blason ${badgeKey}"><span>${badgeKey}</span></span>` : '';
    copy.innerHTML=`<span class="pin-badge">${meta.dynasty}</span><span class="pin-name">${name}</span><span class="pin-date">${meta.date}</span><span class="pin-description">${meta.desc}</span>${badgeHtml}<span class="pin-action">Ouvrir la fiche <b>→</b></span>`;
    el.appendChild(copy);
    el.setAttribute('aria-label', `Ouvrir la fiche de ${name}`);
  });
}


