(function(){
  const overlay=document.getElementById('modal');
  const closeModal=()=>{ if(overlay){overlay.hidden=true;document.body.style.overflow='';} };
  document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();closeModal();}));
  if(overlay) overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  document.addEventListener('click',e=>{
    const b=e.target.closest('.successor-link');
    if(!b) return;
    e.preventDefault(); e.stopPropagation();
    focusRulerPin(b.dataset.successor);
  },true);
})();

/* LYS V20 — fondu de l'image de l'accueil selon le scroll */
(function initHeroImageFade(){
  const hero=document.querySelector('.hero');
  if(!hero) return;

  const reduceMotion=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduceMotion){
    hero.style.setProperty('--hero-image-opacity','1');
    return;
  }

  let ticking=false;
  const update=()=>{
    ticking=false;
    const rect=hero.getBoundingClientRect();
    const start=Math.max(0, -rect.top);
    const fadeDistance=Math.max(280, Math.min(rect.height * 0.72, window.innerHeight * 0.95));
    const progress=Math.min(1, Math.max(0, start / fadeDistance));
    const opacity=Math.pow(1-progress, 1.18);
    hero.style.setProperty('--hero-image-opacity', opacity.toFixed(3));
  };

  const requestUpdate=()=>{
    if(ticking) return;
    ticking=true;
    window.requestAnimationFrame(update);
  };

  window.addEventListener('scroll', requestUpdate, {passive:true});
  window.addEventListener('resize', requestUpdate, {passive:true});
  update();
})();





/* LYS V78 — particules dynastiques */
(function initDynastyParticles(){
  const pins=document.querySelectorAll('.dynasty-pin');
  if(!pins.length) return;
  const dirs=[
    [-82,-40],[-54,-88],[-15,-104],[28,-92],[72,-60],[104,-14],[94,30],[64,72],[12,104],[-38,88],[-82,60],[-108,18],[-98,-22],[-44,-8],[48,8]
  ];
  pins.forEach((pin, idx)=>{
    if(pin.querySelector('.dynasty-particle')) return;
    dirs.forEach(([dx,dy],i)=>{
      const s=document.createElement('span');
      s.className='dynasty-particle';
      s.setAttribute('aria-hidden','true');
      s.style.setProperty('--dx',`${dx + ((idx+i)%3-1)*7}px`);
      s.style.setProperty('--dy',`${dy + (((idx*2)+i)%3-1)*6}px`);
      s.style.setProperty('--delay',`${(i%6)*95}ms`);
      pin.appendChild(s);
    });
  });
})();


// Vue dédiée des présidents dans la catégorie Politique
(function(){
  const toggle=document.getElementById('presidentsToggle');
  const panel=document.getElementById('presidentsPanel');
  if(!toggle||!panel) return;
  toggle.addEventListener('click',()=>{
    const open=toggle.getAttribute('aria-expanded')==='true';
    toggle.setAttribute('aria-expanded',String(!open));
    panel.hidden=open;
  });

  const firstToggle=document.getElementById('firstRepublicToggle');
  const firstPanel=document.getElementById('firstRepublicPanel');
  const secondToggle=document.getElementById('secondRepublicToggle');
  const secondPanel=document.getElementById('secondRepublicPanel');
  const thirdToggle=document.getElementById('thirdRepublicToggle');
  const thirdPanel=document.getElementById('thirdRepublicPanel');
  const fifthToggle=document.getElementById('fifthRepublicToggle');
  const fifthPanel=document.getElementById('fifthRepublicPanel');
  const fourthToggle=document.getElementById('fourthRepublicToggle');
  const fourthPanel=document.getElementById('fourthRepublicPanel');
  const vichyToggle=document.getElementById('vichyToggle');
  const vichyPanel=document.getElementById('vichyPanel');

  // Une seule vue institutionnelle est visible à la fois. Par défaut : Ve République.
  const showRepublic = (era, scroll=true) => {
    const isFirst = era === 'I';
    const isSecond = era === 'II';
    const isThird = era === 'III';
    const isFifth = era === 'V';
    const isFourth = era === 'IV';
    const isVichy = era === 'RV';
    if(firstToggle) firstToggle.setAttribute('aria-expanded', String(isFirst));
    if(secondToggle) secondToggle.setAttribute('aria-expanded', String(isSecond));
    if(thirdToggle) thirdToggle.setAttribute('aria-expanded', String(isThird));
    if(fifthToggle) fifthToggle.setAttribute('aria-expanded', String(isFifth));
    if(fourthToggle) fourthToggle.setAttribute('aria-expanded', String(isFourth));
    if(vichyToggle) vichyToggle.setAttribute('aria-expanded', String(isVichy));
    if(firstPanel) firstPanel.hidden = !isFirst;
    if(secondPanel) secondPanel.hidden = !isSecond;
    if(thirdPanel) thirdPanel.hidden = !isThird;
    if(fifthPanel) fifthPanel.hidden = !isFifth;
    if(fourthPanel) fourthPanel.hidden = !isFourth;
    if(vichyPanel) vichyPanel.hidden = !isVichy;
    if(scroll){
      const target = isFirst ? firstPanel : (isSecond ? secondPanel : (isThird ? thirdPanel : (isFifth ? fifthPanel : (isFourth ? fourthPanel : vichyPanel))));
      if(target) requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'nearest'}));
    }
  };

  if(firstToggle && firstPanel && secondToggle && secondPanel && thirdToggle && thirdPanel && fifthToggle && fifthPanel && fourthToggle && fourthPanel && vichyToggle && vichyPanel){
    // État initial volontairement sur la Ve.
    showRepublic('V', false);
    firstToggle.addEventListener('click',()=>showRepublic('I'));
    secondToggle.addEventListener('click',()=>showRepublic('II'));
    thirdToggle.addEventListener('click',()=>showRepublic('III'));
    vichyToggle.addEventListener('click',()=>showRepublic('RV'));
    fourthToggle.addEventListener('click',()=>showRepublic('IV'));
    fifthToggle.addEventListener('click',()=>showRepublic('V'));
  }
})();

