function openRebuiltPoliticalProfile(name){
  const d = REBUILT_POLITICAL_PROFILES[name];
  const modal = document.getElementById('modal');
  const reader = document.getElementById('reader');
  if(!d || !modal || !reader) return;
  const safe = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const facts = (d.facts || []).map(([label,value]) => '<div class="reader-fact"><span>'+safe(label)+'</span><strong>'+safe(value)+'</strong></div>').join('');
  const sources = (d.sources || []).map(([label,url]) => '<div class="source-row"><span>↗</span><a href="'+safe(url)+'" target="_blank" rel="noreferrer">'+safe(label)+'</a></div>').join('');
  reader.innerHTML = `
    <div class="reader-hero reader-political rebuilt-political-reader">
      <div class="reader-visual">
        <div class="reader-portraits"><img class="portrait" src="${safe(d.portrait)}" alt="Portrait de ${safe(d.title)}"></div>
        <div class="reader-portrait-caption">${safe(d.type)}</div>
      </div>
      <div class="reader-intro">
        <span class="reader-eyebrow">FICHE ENCYCLOPÉDIQUE</span>
        <h2>${safe(d.title)}</h2>
        <p class="reader-lead">${safe(d.role)}</p>
        <div class="reader-facts">${facts}</div>
      </div>
    </div>
    <div class="reader-body">
      <section class="profile-card profile-card-wide">
        <div class="profile-card-kicker">PARCOURS &amp; TRAJECTOIRE</div>
        <h3>${safe(d.title)}</h3>
        <p>${safe(d.history)}</p>
      </section>
      <section class="profile-card profile-card-wide">
        <div class="profile-card-kicker">ACTIVITÉ POLITIQUE</div>
        <h3>Principaux repères</h3>
        <p>${safe(d.achievements)}</p>
      </section>
      <section class="sourcebox">
        <div class="sourcebox-title"><span class="section-kicker">DOCUMENTATION</span><b>Sources utilisées</b></div>
        ${sources || '<div class="source-row"><span>•</span><span>Sources à compléter.</span></div>'}
      </section>
    </div>`;
  modal.hidden = false;
  modal.setAttribute('aria-hidden','false');
  document.body.style.overflow='hidden';
}

/* Intercepte les trois noms avant le rendu générique afin qu'ils restent toujours accessibles. */
if (typeof window !== 'undefined' && typeof window.openTopic === 'function') {
  const __lysOriginalOpenTopic = window.openTopic;
  window.openTopic = function(name){
    if (REBUILT_POLITICAL_PROFILES[name]) return openRebuiltPoliticalProfile(name);
    return __lysOriginalOpenTopic(name);
  };
}



/* LYS — Média v5 : une vraie zone de défilement interne, sans casser les positions relatives. */
(function(){
  const nebula = document.querySelector('.media-nebula');
  if(!nebula || nebula.dataset.mediaScrollV5) return;
  nebula.dataset.mediaScrollV5 = '1';
  const inner = document.createElement('div');
  inner.className = 'media-nebula-scroll-inner';
  const children = [...nebula.children];
  children.forEach(child => inner.appendChild(child));
  nebula.appendChild(inner);
})();

/* LYS — Média v4 : labels cliquables avec focus doux sur chaque groupe. */
(function(){
  const nebula = document.querySelector('.media-nebula');
  if(!nebula || nebula.dataset.mediaLabelV4) return;
  nebula.dataset.mediaLabelV4 = '1';
  const labels = [...nebula.querySelectorAll('.media-zone-label[data-media-zone]')];
  const zones = [...nebula.querySelectorAll('.media-zone')];
  const byKey = key => nebula.querySelector('.media-zone-' + key);
  const clearState = () => zones.forEach(z => z.classList.remove('is-focus','is-muted'));
  labels.forEach(label => {
    label.addEventListener('click', () => {
      const key = label.dataset.mediaZone;
      const zone = byKey(key);
      if(!zone) return;
      const already = zone.classList.contains('is-focus');
      clearState();
      labels.forEach(l => l.classList.remove('is-active'));
      if(already) return;
      zone.classList.add('is-focus');
      labels.forEach(l => { if(l.dataset.mediaZone !== key) l.closest('.media-zone')?.classList.add('is-muted'); });
      label.classList.add('is-active');
      window.setTimeout(() => {
        zone.scrollIntoView({behavior:'smooth', block:'center', inline:'nearest'});
      }, 40);
      window.setTimeout(clearState, 1800);
      window.setTimeout(() => labels.forEach(l => l.classList.remove('is-active')), 1800);
    });
  });
})();

/* LYS — Média v5 : la molette est laissée au défilement natif de la nébuleuse. */
(function(){
  const nebula = document.querySelector('.media-nebula');
  if(!nebula || nebula.dataset.nativeWheelV5) return;
  nebula.dataset.nativeWheelV5 = '1';
  nebula.addEventListener('wheel', function(e){
    if(!e.deltaY) return;
    const atTop = nebula.scrollTop <= 0;
    const atBottom = nebula.scrollTop + nebula.clientHeight >= nebula.scrollHeight - 1;
    if((atTop && e.deltaY < 0) || (atBottom && e.deltaY > 0)) return;
    e.stopPropagation();
  }, {passive:true});
})();


/* LYS — Nébuleuse V6 : fusion de tous les médias en un seul amas organique. */
(function rebuildMediaNebulaV6(){
  const nebula=document.querySelector('.media-nebula');
  if(!nebula || nebula.dataset.v6Unified) return;
  nebula.dataset.v6Unified='1';
  const zones=[...nebula.querySelectorAll('.media-zone')];
  if(zones.length!==3) return;
  const publicZone=zones.find(z=>z.classList.contains('media-zone-public'));
  const allLogos=[];
  zones.forEach(zone=>{
    zone.querySelectorAll('.media-logo').forEach(logo=>{
      logo.dataset.mediaCategory=zone.classList.contains('media-zone-public')?'public':zone.classList.contains('media-zone-private')?'private':'community';
      allLogos.push(logo);
    });
  });
  const master=publicZone.querySelector('.media-logo-grid');
  if(!master) return;
  master.classList.add('media-master-grid');
  master.setAttribute('aria-label','Tous les médias');
  zones.slice(1).forEach(z=>{
    const grid=z.querySelector('.media-logo-grid');
    if(grid) grid.innerHTML='';
  });
  const seed=n=>{const x=Math.sin(n*91.731+17.31)*43758.5453;return x-Math.floor(x)};
  const order=allLogos.map((logo,i)=>({logo,i,w:0,h:0,x:50,y:50}));
  const W=Math.max(nebula.clientWidth,1200), H=Math.max(nebula.clientHeight,760);
  order.forEach(o=>{
    const scale=parseFloat(o.logo.style.getPropertyValue('--scale'))||1;
    const base=Math.min(84,Math.max(48,W*.048));
    o.w=base*scale+18; o.h=base*scale+18;
  });
  // Les plus influents sont placés plus près du cœur ; les autres forment une périphérie dense.
  const influenceScore=o=>{const s=parseFloat(o.logo.style.getPropertyValue('--scale'))||1;return s;};
  order.sort((a,b)=>influenceScore(b)-influenceScore(a));
  const placed=[];
  order.forEach((o,idx)=>{
    let placedOk=false;
    for(let attempt=0;attempt<900 && !placedOk;attempt++){
      const t=(idx*2.399963 + attempt*.071) % (Math.PI*2);
      const u=(idx+1)/(order.length+3);
      const radius=(Math.sqrt(u)*0.86 + seed(idx*7+attempt)*.04) * Math.min(W*.38,H*.34);
      const jitter=(seed(idx*13+attempt*3)-.5)*44;
      const cx=W/2 + Math.cos(t)*radius + jitter;
      const cy=H/2 + Math.sin(t)*radius*.72 + (seed(idx*17+attempt*5)-.5)*28;
      const x=Math.max(o.w,Math.min(W-o.w,cx)), y=Math.max(o.h,yClamp(H,cy,o.h));
      const clear=placed.every(p=>{const dx=x-p.x,dy=y-p.y;return Math.hypot(dx,dy)>(o.w+p.w)*.60;});
      if(clear){o.x=x;o.y=y;placed.push(o);placedOk=true;}
    }
    if(!placedOk){
      o.x=W/2+(seed(idx*19)-.5)*W*.55;o.y=H/2+(seed(idx*23)-.5)*H*.55;placed.push(o);
    }
  });
  function yClamp(h,y,r){return Math.max(r,Math.min(h-r,y));}
  placed.forEach((o,idx)=>{
    const x=o.x/W*100, y=o.y/H*100;
    o.logo.style.setProperty('--x',x.toFixed(3)+'%');
    o.logo.style.setProperty('--y',y.toFixed(3)+'%');
    const n=seed(idx*29+5);
    o.logo.style.setProperty('--float-x',((n-.5)*3.5).toFixed(2)+'px');
    o.logo.style.setProperty('--float-y',((seed(idx*31+7)-.5)*3.5).toFixed(2)+'px');
    o.logo.style.setProperty('--float-dur',(15+n*8).toFixed(2)+'s');
    o.logo.style.setProperty('--float-delay',(-n*16).toFixed(2)+'s');
    master.appendChild(o.logo);
  });
  // Etiquettes pilotées par la position de la souris sur trois zones souples.
  const labels={public:publicZone.querySelector('.media-zone-label'),private:zones.find(z=>z.classList.contains('media-zone-private')).querySelector('.media-zone-label'),community:zones.find(z=>z.classList.contains('media-zone-community')).querySelector('.media-zone-label')};
  const hotspots={public:{x:.25,y:.33,r:.23},private:{x:.75,y:.34,r:.23},community:{x:.50,y:.78,r:.25}};
  let current=null;
  const setHover=key=>{
    Object.entries(labels).forEach(([k,l])=>l?.closest('.media-zone')?.classList.toggle('is-hovered',k===key));
    current=key;
  };
  nebula.addEventListener('mousemove',e=>{
    const r=nebula.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;
    let best=null,score=Infinity;
    for(const [k,p] of Object.entries(hotspots)){const d=Math.hypot((x-p.x)*1.05,(y-p.y));if(d<p.r&&d<score){score=d;best=k;}}
    if(best!==current)setHover(best);
  });
  nebula.addEventListener('mouseleave',()=>setHover(null));
  Object.values(labels).forEach(l=>l?.addEventListener('click',e=>e.preventDefault()));
})();

/* LYS V7 — refonte complète de la nébuleuse : grande surface unique, trois cœurs imbriqués. */
(function rebuildMediaNebulaV7(){
  const nebula=document.querySelector('.media-nebula');
  const inner=nebula?.querySelector('.media-nebula-scroll-inner');
  if(!nebula || !inner || nebula.dataset.v7Unified) return;
  nebula.dataset.v7Unified='1';

  const zones=[...nebula.querySelectorAll('.media-zone')];
  const publicZone=zones.find(z=>z.classList.contains('media-zone-public'));
  const privateZone=zones.find(z=>z.classList.contains('media-zone-private'));
  const communityZone=zones.find(z=>z.classList.contains('media-zone-community'));
  const master=nebula.querySelector('.media-master-grid') || publicZone?.querySelector('.media-logo-grid');
  if(!master) return;
  if(master.parentElement!==inner) inner.appendChild(master);
  master.classList.add('media-master-grid');

  const logos=[...master.querySelectorAll('.media-logo')];
  const seed=n=>{const x=Math.sin(n*127.17+11.73)*43758.5453;return x-Math.floor(x);};
  const catOf=logo=>logo.dataset.mediaCategory || (logo.closest('.media-zone')?.classList.contains('media-zone-private')?'private':logo.closest('.media-zone')?.classList.contains('media-zone-community')?'community':'public');
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));

  function layout(){
    const W=Math.max(inner.clientWidth,900), H=Math.max(inner.clientHeight,760);
    master.style.width='100%'; master.style.height='100%';

    const center={x:W*.51,y:H*.50};
    const anchors={
      public:{x:W*.35,y:H*.38},
      private:{x:W*.66,y:H*.36},
      community:{x:W*.50,y:H*.66}
    };

    // Priorité d'influence : les grands médias occupent la zone centrale, les autres se déploient autour.
    const data=logos.map((logo,i)=>{
      const scale=parseFloat(logo.style.getPropertyValue('--scale'))||1;
      const base=Math.max(52,Math.min(84,W*.048));
      const size=base*scale;
      return {logo,i,cat:catOf(logo),scale,size,r:size*.50+9,x:center.x,y:center.y};
    }).sort((a,b)=>b.scale-a.scale);

    const placed=[];
    data.forEach((o,idx)=>{
      const a=anchors[o.cat] || center;
      let best=null;
      // Recherche en spirale : on privilégie le cœur, puis les anneaux périphériques.
      for(let attempt=0;attempt<1600;attempt++){
        const angle=(idx*2.399963 + attempt*.137 + (o.cat==='private'?.4:o.cat==='community'?2.0:0))%(Math.PI*2);
        const radial=(attempt<70 ? Math.sqrt(attempt/70)*42 : 42 + Math.sqrt(attempt-70)*8.2);
        const jitterX=(seed(o.i*19+attempt*3)-.5)*18;
        const jitterY=(seed(o.i*23+attempt*5)-.5)*14;
        // Mélange progressif entre le cœur commun et le cœur de la catégorie.
        const blend=Math.min(1,(radial/250)*.82+.12+seed(o.i+9)*.08);
        const cx=center.x+(a.x-center.x)*blend + Math.cos(angle)*radial + jitterX;
        const cy=center.y+(a.y-center.y)*blend + Math.sin(angle)*radial*.72 + jitterY;
        const x=clamp(cx,o.r+12,W-o.r-12), y=clamp(cy,o.r+12,H-o.r-12);
        const clear=placed.every(p=>Math.hypot(x-p.x,y-p.y) > (o.r+p.r+3.5));
        if(clear){best={x,y};break;}
      }
      if(!best){
        const angle=idx*2.399963; const rr=120+Math.sqrt(idx)*8;
        best={x:clamp(center.x+Math.cos(angle)*rr,o.r+12,W-o.r-12),y:clamp(center.y+Math.sin(angle)*rr*.7,o.r+12,H-o.r-12)};
      }
      o.x=best.x;o.y=best.y;placed.push(o);
    });

    // Relaxation légère globale : évite les collisions résiduelles sans rendre les amas trop réguliers.
    for(let iter=0;iter<90;iter++){
      let moved=false;
      for(let i=0;i<placed.length;i++) for(let j=i+1;j<placed.length;j++){
        const A=placed[i],B=placed[j],dx=B.x-A.x,dy=B.y-A.y,d=Math.hypot(dx,dy),min=A.r+B.r+2;
        if(d<min){
          const ang=d<.01?(A.i*1.71+B.i*.93):Math.atan2(dy,dx),push=(min-d)*.36;
          A.x-=Math.cos(ang)*push; A.y-=Math.sin(ang)*push;
          B.x+=Math.cos(ang)*push; B.y+=Math.sin(ang)*push; moved=true;
        }
      }
      if(!moved) break;
    }

    placed.forEach((o,idx)=>{
      o.logo.style.setProperty('--x',(o.x/W*100).toFixed(3)+'%');
      o.logo.style.setProperty('--y',(o.y/H*100).toFixed(3)+'%');
      o.logo.style.setProperty('--float-x',((seed(idx*31+2)-.5)*2.6).toFixed(2)+'px');
      o.logo.style.setProperty('--float-y',((seed(idx*37+4)-.5)*2.6).toFixed(2)+'px');
      o.logo.style.setProperty('--float-dur',(13.5+seed(idx*41+5)*7.5).toFixed(2)+'s');
      o.logo.style.setProperty('--float-delay',(-seed(idx*43+6)*14).toFixed(2)+'s');
      o.logo.style.setProperty('--rot',((seed(idx*47+8)-.5)*4).toFixed(2)+'deg');
    });

    // Étiquettes : trois points fixes autour de l'amas, avec des capsules discrètes.
    const specs=[
      [publicZone,.34,.28],
      [privateZone,.72,.28],
      [communityZone,.50,.79]
    ];
    specs.forEach(([zone,x,y])=>{
      if(!zone) return;
      zone.style.setProperty('--label-x',(x*100)+'%');
      zone.style.setProperty('--label-y',(y*100)+'%');
    });
  }

  let raf=0;
  const relayout=()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(layout);};
  window.addEventListener('resize',relayout,{passive:true});
  if(document.fonts?.ready) document.fonts.ready.then(relayout); else relayout();
  layout();
})();

/* V8 — placement totalement unifié : les catégories n'influencent plus la géométrie. */
(function rebuildMediaNebulaV8(){
  const nebula=document.querySelector('.media-nebula');
  const inner=nebula?.querySelector('.media-nebula-scroll-inner');
  const master=inner?.querySelector('.media-master-grid');
  if(!nebula || !inner || !master || nebula.dataset.v8Unified) return;
  nebula.dataset.v8Unified='1';
  const logos=[...master.querySelectorAll('.media-logo')];
  const seed=n=>{const x=Math.sin(n*157.31+19.71)*43758.5453;return x-Math.floor(x);};
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function layout(){
    const W=Math.max(inner.clientWidth,1100), H=Math.max(inner.clientHeight,780);
    master.style.width='100%'; master.style.height='100%';
    const center={x:W*.5,y:H*.51};
    const data=logos.map((logo,i)=>{
      const scale=parseFloat(logo.style.getPropertyValue('--scale'))||1;
      const base=Math.max(50,Math.min(86,W*.048));
      const size=base*scale;
      return {logo,i,scale,size,r:size*.5+14,x:center.x,y:center.y};
    }).sort((a,b)=>b.scale-a.scale);
    const placed=[];
    const golden=Math.PI*(3-Math.sqrt(5));
    data.forEach((o,idx)=>{
      let best=null;
      const t=(idx+0.65)/data.length;
      // Distribution en spirale aplatie : elle remplit toute la nébuleuse,
      // sans retomber dans une simple grille ni dans deux moitiés.
      const radialMax=Math.min(W*.43,H*.43);
      const baseRadius=Math.pow(t,.72)*radialMax;
      const baseAngle=idx*golden + seed(idx*7)*.48;
      for(let attempt=0;attempt<2200 && !best;attempt++){
        const angle=baseAngle + attempt*.087;
        const rr=baseRadius + (seed(idx*17+attempt)*2-1)*(18 + baseRadius*.08);
        const x=clamp(center.x+Math.cos(angle)*rr,o.r+24,W-o.r-24);
        const y=clamp(center.y+Math.sin(angle)*rr*.76,o.r+24,H-o.r-24);
        const clear=placed.every(p=>Math.hypot(x-p.x,y-p.y)>(o.r+p.r+7));
        if(clear) best={x,y};
      }
      if(!best){
        const angle=baseAngle, rr=Math.min(radialMax*.72, 180+idx*2.4);
        best={x:clamp(center.x+Math.cos(angle)*rr,o.r+24,W-o.r-24),y:clamp(center.y+Math.sin(angle)*rr*.75,o.r+24,H-o.r-24)};
      }
      o.x=best.x;o.y=best.y;placed.push(o);
    });
    // Relaxation globale avec marge confortable pour les gros logos.
    for(let iter=0;iter<220;iter++){
      let moved=false;
      for(let i=0;i<placed.length;i++) for(let j=i+1;j<placed.length;j++){
        const A=placed[i],B=placed[j],dx=B.x-A.x,dy=B.y-A.y,d=Math.hypot(dx,dy),min=A.r+B.r+7;
        if(d<min){
          const a=d<.01?(A.i*1.91+B.i*.77):Math.atan2(dy,dx),push=(min-d)*.46;
          A.x-=Math.cos(a)*push;A.y-=Math.sin(a)*push;B.x+=Math.cos(a)*push;B.y+=Math.sin(a)*push;moved=true;
        }
      }
      // Reborde doux : les logos périphériques restent dans la nébuleuse.
      for(const o of placed){
        o.x=clamp(o.x,o.r+24,W-o.r-24); o.y=clamp(o.y,o.r+24,H-o.r-24);
      }
      if(!moved) break;
    }
    placed.forEach((o,idx)=>{
      o.logo.style.setProperty('--x',(o.x/W*100).toFixed(3)+'%');
      o.logo.style.setProperty('--y',(o.y/H*100).toFixed(3)+'%');
      // Apesanteur plus perceptible : chaque logo a sa propre amplitude et vitesse.
      o.logo.style.setProperty('--float-x',((seed(idx*31+2)-.5)*6.5).toFixed(2)+'px');
      o.logo.style.setProperty('--float-y',((seed(idx*37+4)-.5)*5.8).toFixed(2)+'px');
      o.logo.style.setProperty('--float-dur',(10.5+seed(idx*41+5)*7.5).toFixed(2)+'s');
      o.logo.style.setProperty('--float-delay',(-seed(idx*43+6)*16).toFixed(2)+'s');
      o.logo.style.setProperty('--rot',((seed(idx*47+8)-.5)*4.8).toFixed(2)+'deg');
    });
  }
  let raf=0;
  const relayout=()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(layout);};
  window.addEventListener('resize',relayout,{passive:true});
  if(document.fonts?.ready) document.fonts.ready.then(relayout); else relayout();
  layout();
})();


