/* LYS — carrousel accueil : moteur unique et robuste. */
(function initHeroGalleryV5(){
  const gallery=document.getElementById('heroGallery');
  if(!gallery)return;
  const slides=[...gallery.querySelectorAll('.hero-slide')];
  const buttons=[...gallery.querySelectorAll('.hero-gallery-btn')];
  const caption=document.getElementById('heroActiveCaption');
  if(!slides.length)return;
  let current=0,lastChange=performance.now(),raf=0,paused=false;
  const interval=6200;
  const syncCaption=()=>{
    const slide=slides[current];
    if(!slide||!caption)return;
    const img=slide.querySelector('img');
    const title=slide.dataset.title||img?.getAttribute('alt')||'';
    const meta=slide.dataset.meta||'';
    const strong=caption.querySelector('strong'); const em=caption.querySelector('em');
    if(strong)strong.textContent=title;
    if(em)em.textContent=meta;
    buttons.forEach((btn,i)=>{
      const active=i===current;
      btn.setAttribute('aria-label',`Afficher ${slides[i].dataset.title||slides[i].querySelector('img')?.getAttribute('alt')||''}`);
      btn.setAttribute('aria-pressed',active?'true':'false');
    });
  };
  const render=()=>{
    slides.forEach((slide,i)=>{
      const active=i===current;
      slide.classList.toggle('is-active',active);
      slide.setAttribute('aria-hidden',active?'false':'true');
    });
    buttons.forEach((btn,i)=>{
      const active=i===current; btn.classList.toggle('is-active',active); btn.setAttribute('aria-pressed',active?'true':'false');
    });
    syncCaption();
  };
  const show=i=>{current=(i+slides.length)%slides.length;lastChange=performance.now();render();};
  buttons.forEach((btn,i)=>btn.addEventListener('click',()=>show(i)));
  gallery.addEventListener('mouseenter',()=>paused=true);
  gallery.addEventListener('mouseleave',()=>{paused=false;lastChange=performance.now();});
  gallery.addEventListener('focusin',()=>paused=true);
  gallery.addEventListener('focusout',e=>{if(!gallery.contains(e.relatedTarget))paused=false;});
  document.addEventListener('visibilitychange',()=>{lastChange=performance.now();});
  render();
  const loop=now=>{if(!paused&&!document.hidden&&now-lastChange>=interval)show(current+1);raf=requestAnimationFrame(loop);};
  cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);
})();;;


// Cocarde placée dans l'en-tête de la section Présidents, à gauche des boutons de République.
(function initRepublicSymbols(){
  const init=()=>{
    const presidentsCocardeButton=document.getElementById('presidentsCocardeButton');
    const overlay=document.getElementById('republicSymbolsOverlay');
    const closeButton=document.getElementById('republicSymbolsClose');
    if(!presidentsCocardeButton || !overlay) return;

    const open=()=>{
      overlay.hidden=false;
      overlay.setAttribute('aria-hidden','false');
      document.body.classList.add('republic-symbols-open');
      document.body.style.overflow='hidden';
      setTimeout(()=>closeButton?.focus(),0);
    };
    const close=()=>{
      overlay.hidden=true;
      overlay.setAttribute('aria-hidden','true');
      document.body.classList.remove('republic-symbols-open');
      document.body.style.overflow='';
      presidentsCocardeButton.focus({preventScroll:true});
    };

    presidentsCocardeButton.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();open();});
    closeButton?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();close();});
    overlay.querySelector('[data-close-republic-symbols]')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();close();});
    overlay.addEventListener('click',e=>{if(e.target===overlay) close();});
    document.addEventListener('keydown',e=>{
      if(e.key==='Escape' && !overlay.hidden){e.preventDefault();close();}
    });
  };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();


/* Médias — filtres rapides PB / PV / CO / T */
(function initMediaCategoryFilters(){
  const nebula=document.querySelector('.media-nebula');
  if(!nebula || nebula.dataset.mediaFiltersReady) return;
  const buttons=[...nebula.querySelectorAll('.media-filter-btn')];
  const zones={
    public:nebula.querySelector('.media-zone-public'),
    private:nebula.querySelector('.media-zone-private'),
    community:nebula.querySelector('.media-zone-community')
  };
  if(!buttons.length || !zones.public || !zones.private || !zones.community) return;
  nebula.dataset.mediaFiltersReady='1';
  const labels={all:'Tous',public:'Publique',private:'Privé',community:'Communautaire'};
  function apply(filter){
    const value=filter==='all'?'all':filter;
    nebula.dataset.mediaFilter=value;
    buttons.forEach(btn=>{
      const active=btn.dataset.mediaFilter===value;
      btn.classList.toggle('is-active',active);
      btn.setAttribute('aria-pressed',String(active));
      btn.setAttribute('aria-label',labels[btn.dataset.mediaFilter]);
    });
    Object.entries(zones).forEach(([key,zone])=>zone.classList.toggle('media-filter-hidden',value!=='all' && key!==value));
  }
  buttons.forEach(btn=>btn.addEventListener('click',()=>apply(btn.dataset.mediaFilter)));
  apply('all');
})();

/* Médias — filtre V2 : recompose réellement l'amas selon la catégorie sélectionnée. */
(function initMediaCategoryFiltersV2(){
  const nebula=document.querySelector('.media-nebula');
  const master=nebula?.querySelector('.media-master-grid');
  if(!nebula || !master || nebula.dataset.mediaFiltersV2Ready) return;
  const buttons=[...nebula.querySelectorAll('.media-filter-btn')];
  const logos=[...master.querySelectorAll('.media-logo')];
  if(!buttons.length || !logos.length) return;
  nebula.dataset.mediaFiltersV2Ready='1';

  const seed=n=>{const x=Math.sin(n*131.731+23.19)*43758.5453;return x-Math.floor(x);};
  const original=new Map();
  logos.forEach((logo,i)=>{
    const cat=logo.dataset.mediaCategory || 'community';
    logo.dataset.mediaCategory=cat;
    original.set(logo,{
      x:logo.style.getPropertyValue('--x')||'50%',
      y:logo.style.getPropertyValue('--y')||'50%',
      i
    });
  });

  function compact(logosToPlace){
    const W=Math.max(master.clientWidth,900), H=Math.max(master.clientHeight,720);
    const center={x:W*.5,y:H*.51};
    const items=logosToPlace.map((logo,i)=>{
      const scale=parseFloat(logo.style.getPropertyValue('--scale'))||1;
      const base=Math.max(48,Math.min(84,W*.048));
      const radius=base*scale*.54+10;
      return {logo,i,scale,radius,x:center.x,y:center.y};
    }).sort((a,b)=>b.scale-a.scale);
    const placed=[];
    items.forEach((o,idx)=>{
      let best=null;
      for(let attempt=0;attempt<1500 && !best;attempt++){
        const angle=idx*2.399963+attempt*.118;
        const radial=(Math.sqrt((idx+1)/(items.length+2))*.44+.03)*Math.min(W,H)*.78;
        const x=Math.max(o.radius+14,Math.min(W-o.radius-14,center.x+Math.cos(angle)*radial+(seed(idx*13+attempt)-.5)*26));
        const y=Math.max(o.radius+14,Math.min(H-o.radius-14,center.y+Math.sin(angle)*radial*.72+(seed(idx*17+attempt)-.5)*20));
        const clear=placed.every(p=>Math.hypot(x-p.x,y-p.y)>o.radius+p.radius+4);
        if(clear) best={x,y};
      }
      if(!best){
        const a=idx*2.399963,r=120+idx*2.3;
        best={x:Math.max(o.radius+14,Math.min(W-o.radius-14,center.x+Math.cos(a)*r)),y:Math.max(o.radius+14,Math.min(H-o.radius-14,center.y+Math.sin(a)*r*.72))};
      }
      o.x=best.x;o.y=best.y;placed.push(o);
    });
    for(let iter=0;iter<80;iter++){
      let moved=false;
      for(let i=0;i<placed.length;i++) for(let j=i+1;j<placed.length;j++){
        const A=placed[i],B=placed[j],dx=B.x-A.x,dy=B.y-A.y,d=Math.hypot(dx,dy),min=A.radius+B.radius+3;
        if(d<min){
          const a=d<.01?(A.i*1.71+B.i*.91):Math.atan2(dy,dx),push=(min-d)*.42;
          A.x-=Math.cos(a)*push;A.y-=Math.sin(a)*push;B.x+=Math.cos(a)*push;B.y+=Math.sin(a)*push;moved=true;
        }
      }
      if(!moved) break;
    }
    placed.forEach((o,idx)=>{
      o.logo.style.setProperty('--x',(o.x/W*100).toFixed(3)+'%');
      o.logo.style.setProperty('--y',(o.y/H*100).toFixed(3)+'%');
      o.logo.style.setProperty('--float-delay',(-idx*.83).toFixed(2)+'s');
    });
  }

  function restoreAll(){
    logos.forEach(logo=>{
      const pos=original.get(logo);
      logo.style.setProperty('--x',pos.x);
      logo.style.setProperty('--y',pos.y);
      logo.classList.remove('media-category-hidden');
      logo.classList.add('media-category-visible');
    });
  }

  function apply(filter){
    buttons.forEach(btn=>{
      const active=btn.dataset.mediaFilter===filter;
      btn.classList.toggle('is-active',active);
      btn.setAttribute('aria-pressed',String(active));
    });
    const visible=filter==='all'?logos:logos.filter(logo=>(logo.dataset.mediaCategory||'community')===filter);
    logos.forEach(logo=>{
      const keep=visible.includes(logo);
      logo.classList.toggle('media-category-hidden',!keep);
      logo.classList.toggle('media-category-visible',keep);
    });
    nebula.dataset.mediaFilter=filter;
    if(filter==='all') restoreAll(); else compact(visible);
  }

  buttons.forEach(btn=>btn.addEventListener('click',()=>apply(btn.dataset.mediaFilter||'all')));
  apply('all');
  window.addEventListener('resize',()=>{
    const current=nebula.dataset.mediaFilter||'all';
    if(current!=='all') compact(logos.filter(logo=>(logo.dataset.mediaCategory||'community')===current));
  },{passive:true});
})();

/* LYS V12 — champ spatial animé, sans toucher au moteur des filtres. */
(function enhanceNebulaMotionV12(){
  const nebula=document.querySelector('.media-nebula');
  const inner=nebula?.querySelector('.media-nebula-scroll-inner');
  if(!nebula || !inner || nebula.dataset.spaceMotionV12) return;
  nebula.dataset.spaceMotionV12='1';
  const seed=n=>{const x=Math.sin(n*73.731+9.17)*43758.5453;return x-Math.floor(x);};

  const live=document.createElement('div');
  live.className='nebula-live-layer';
  live.setAttribute('aria-hidden','true');
  inner.insertBefore(live,inner.firstChild);

  const stars=document.createElement('div');
  stars.className='nebula-star-field';
  stars.setAttribute('aria-hidden','true');
  for(let i=0;i<92;i++){
    const star=document.createElement('span');
    star.className='nebula-star';
    star.style.setProperty('--sx',(2+seed(i*3+1)*96).toFixed(2)+'%');
    star.style.setProperty('--sy',(2+seed(i*5+2)*96).toFixed(2)+'%');
    star.style.setProperty('--ss',(0.8+seed(i*7+3)*2.0).toFixed(2)+'px');
    star.style.setProperty('--so',(0.28+seed(i*11+4)*0.68).toFixed(2));
    star.style.setProperty('--sd',(2.8+seed(i*13+5)*5.8).toFixed(2)+'s');
    star.style.setProperty('--sdelay',(-seed(i*17+6)*8).toFixed(2)+'s');
    stars.appendChild(star);
  }
  inner.insertBefore(stars,inner.firstChild.nextSibling);

  const shooting=nebula.querySelector('.media-shooting-stars');
  if(shooting){
    shooting.querySelectorAll('.media-shooting-star').forEach((star,i)=>{
      star.style.setProperty('--sx',(8+seed(i*19+2)*82).toFixed(2)+'%');
      star.style.setProperty('--sy',(5+seed(i*23+3)*84).toFixed(2)+'%');
      star.style.setProperty('--angle',(-18-seed(i*29+4)*24).toFixed(2)+'deg');
      star.style.setProperty('--dur',(5.2+seed(i*31+5)*4.2).toFixed(2)+'s');
      star.style.setProperty('--delay',(-seed(i*37+6)*9.5).toFixed(2)+'s');
    });
  }

  nebula.querySelectorAll('.media-master-grid .media-logo').forEach((logo,i)=>{
    const fx=Math.max(-5,Math.min(5,(parseFloat(logo.style.getPropertyValue('--float-x'))||0)*1.65));
    const fy=Math.max(-5,Math.min(5,(parseFloat(logo.style.getPropertyValue('--float-y'))||0)*1.55));
    logo.style.setProperty('--float-x',fx.toFixed(2)+'px');
    logo.style.setProperty('--float-y',fy.toFixed(2)+'px');
    logo.style.setProperty('--float-dur',(11.5+seed(i*41+7)*7.5).toFixed(2)+'s');
    logo.style.setProperty('--float-delay',(-seed(i*43+8)*12).toFixed(2)+'s');
  });
})();

/* V13 — mouvement autonome des logos + étoiles filantes fluides. */
(function enhanceSpaceMotionV13(){
  const nebula=document.querySelector('.media-nebula');
  const inner=nebula?.querySelector('.media-nebula-scroll-inner');
  if(!nebula||!inner||nebula.dataset.spaceMotionV13) return;
  nebula.dataset.spaceMotionV13='1';
  const seed=n=>{const x=Math.sin(n*83.117+4.91)*43758.5453;return x-Math.floor(x);};

  const old=nebula.querySelector('.nebula-meteor-field');
  old?.remove();
  const meteorField=document.createElement('div');
  meteorField.className='nebula-meteor-field';
  meteorField.setAttribute('aria-hidden','true');
  for(let i=0;i<11;i++){
    const m=document.createElement('span');
    m.className='nebula-meteor';
    m.style.setProperty('--mx',(8+seed(i*5+1)*84).toFixed(2)+'%');
    m.style.setProperty('--my',(5+seed(i*7+2)*84).toFixed(2)+'%');
    m.style.setProperty('--ml',(130+seed(i*11+3)*120).toFixed(0)+'px');
    m.style.setProperty('--ma',(-22-seed(i*13+4)*24).toFixed(2)+'deg');
    m.style.setProperty('--mdx',(-320-seed(i*17+5)*260).toFixed(0)+'px');
    m.style.setProperty('--mdy',(150+seed(i*19+6)*180).toFixed(0)+'px');
    m.style.setProperty('--md',(7.5+seed(i*23+7)*5.5).toFixed(2)+'s');
    m.style.setProperty('--mdd',(-seed(i*29+8)*13).toFixed(2)+'s');
    meteorField.appendChild(m);
  }
  inner.insertBefore(meteorField,inner.firstChild);

  nebula.querySelectorAll('.media-master-grid .media-logo').forEach((logo,i)=>{
    const ampX=1.8+seed(i*31+2)*3.8;
    const ampY=1.7+seed(i*37+4)*3.6;
    const rot=.25+seed(i*41+5)*1.0;
    logo.style.setProperty('--float-start-x',(-ampX*.7).toFixed(2)+'px');
    logo.style.setProperty('--float-start-y',(ampY*.4).toFixed(2)+'px');
    logo.style.setProperty('--float-mid-x',(ampX*.15).toFixed(2)+'px');
    logo.style.setProperty('--float-mid-y',(-ampY*.45).toFixed(2)+'px');
    logo.style.setProperty('--float-mid2-x',(-ampX*.25).toFixed(2)+'px');
    logo.style.setProperty('--float-mid2-y',(ampY*.3).toFixed(2)+'px');
    logo.style.setProperty('--float-end-x',(ampX*.7).toFixed(2)+'px');
    logo.style.setProperty('--float-end-y',(-ampY*.5).toFixed(2)+'px');
    logo.style.setProperty('--rot-start',(-rot).toFixed(2)+'deg');
    logo.style.setProperty('--rot-mid',(rot*.35).toFixed(2)+'deg');
    logo.style.setProperty('--rot-mid2',(-rot*.2).toFixed(2)+'deg');
    logo.style.setProperty('--rot-end',rot.toFixed(2)+'deg');
    logo.style.setProperty('--float-dur',(16+seed(i*43+6)*12).toFixed(2)+'s');
    logo.style.setProperty('--float-delay',(-seed(i*47+7)*18).toFixed(2)+'s');
  });
})();

/* V15 — étoiles filantes indépendantes, créées hors des anciens moteurs. */
(function mountMeteorFXV15(){
  const nebula=document.querySelector('.media-nebula');
  if(!nebula || nebula.querySelector('.meteor-fx-v15')) return;
  const field=document.createElement('div');
  field.className='meteor-fx-v15';
  field.setAttribute('aria-hidden','true');
  const seed=n=>{const x=Math.sin(n*143.91+8.17)*43758.5453;return x-Math.floor(x);};
  for(let i=0;i<14;i++){
    const m=document.createElement('span');
    m.className='meteor-fx-item';
    m.style.setProperty('--msx',(4+seed(i*7+1)*91).toFixed(2)+'%');
    m.style.setProperty('--msy',(4+seed(i*11+2)*86).toFixed(2)+'%');
    m.style.setProperty('--msl',(150+seed(i*13+3)*170).toFixed(0)+'px');
    m.style.setProperty('--msa',(-20-seed(i*17+4)*34).toFixed(2)+'deg');
    m.style.setProperty('--msdx',(-260-seed(i*19+5)*360).toFixed(0)+'px');
    m.style.setProperty('--msdy',(140+seed(i*23+6)*260).toFixed(0)+'px');
    m.style.setProperty('--msd',(5.8+seed(i*29+7)*4.6).toFixed(2)+'s');
    m.style.setProperty('--mss',(-seed(i*31+8)*12).toFixed(2)+'s');
    field.appendChild(m);
  }
  nebula.appendChild(field);
})();

const DEFINITIONS = {"Discrimination":"Traitement défavorable ou inégal d’une personne ou d’un groupe en raison d’une caractéristique réelle ou supposée. Elle suppose une différence de traitement fondée sur un critère qui conduit à désavantager une personne ou un groupe. En droit, certaines discriminations sont explicitement interdites.","racisme":"Idéologie, préjugé ou pratique qui hiérarchise ou exclut des personnes en fonction de leur origine ou de caractéristiques racialisées. Le terme peut viser une doctrine, un préjugé ou des pratiques discriminatoires. Larousse rattache notamment le mot à l’idée de hiérarchisation des groupes humains et à l’hostilité envers une catégorie de personnes.","sexisme":"Préjugé, distinction ou comportement défavorable fondé sur le sexe ou le genre. Il peut se manifester dans les représentations, les propos, les comportements ou les règles d’une organisation. Le concept ne se limite donc pas aux insultes et peut aussi concerner des inégalités systématiques.","homophobie":"Hostilité, rejet ou discrimination envers les personnes homosexuelles ou l’homosexualité. Le terme couvre les manifestations individuelles ou collectives de rejet. Il peut concerner les personnes, les couples, les pratiques ou les représentations liées à l’homosexualité.","transphobie":"Hostilité, rejet ou discrimination envers les personnes transgenres ou leur identité de genre. Elle peut prendre la forme de propos hostiles, de discriminations, de violences ou de refus de reconnaître une personne trans. Le terme décrit une hostilité, pas un jugement médical.","christianophobie":"Terme employé pour désigner une hostilité ou des discriminations visant le christianisme ou des chrétiens ; son usage et sa définition peuvent être discutés selon les contextes. Le terme est utilisé dans certains débats pour qualifier des actes ou discours hostiles au christianisme. Son périmètre est contesté : il faut distinguer critique d’une religion, discrimination de croyants et persécution.","antisémitisme":"Hostilité, préjugé ou discrimination envers les Juifs, en tant que personnes, peuple ou religion. Il peut prendre des formes religieuses, raciales, politiques ou conspirationnistes selon les périodes. Le terme est historiquement distinct de la simple critique d’une institution ou d’une politique.","islamophobie":"Terme désignant des préjugés, hostilités ou discriminations visant des musulmans ou, selon les usages, l’islam ; sa définition fait l’objet de débats terminologiques. Le mot est employé pour décrire une hostilité visant les musulmans, et parfois une hostilité visant l’islam comme religion. Son périmètre fait l’objet de débats, notamment sur la distinction entre critique religieuse et discrimination des personnes.","âgisme":"Préjugés ou discriminations fondés sur l’âge, touchant notamment les personnes âgées mais pouvant viser tout groupe d’âge. Il peut viser les jeunes comme les personnes âgées, même si le terme est surtout utilisé à propos du vieillissement. Il se retrouve dans les attitudes, le recrutement, l’accès aux services ou les représentations sociales.","validisme":"Système de représentations et de pratiques qui dévalorise ou exclut les personnes handicapées par rapport aux personnes valides. La notion met l’accent sur les normes sociales qui privilégient les personnes valides et peuvent produire des obstacles pour les personnes handicapées. Elle est utilisée notamment dans les études sur le handicap et l’inclusion.","préjugé":"Jugement formé à l’avance, souvent sans connaissance suffisante des faits ou de la personne concernée. Un préjugé peut être favorable ou défavorable, mais il repose sur une appréciation antérieure à l’examen individuel du cas. Il peut nourrir des stéréotypes ou des comportements discriminatoires.","stéréotype":"Représentation simplifiée et généralisée attribuée à un groupe ou à une catégorie de personnes. Un stéréotype simplifie une réalité complexe et attribue des caractéristiques supposées communes à un groupe. Il peut être positif, négatif ou ambivalent, mais devient problématique lorsqu’il sert à enfermer les personnes dans une catégorie.","exclusion":"Fait d’écarter une personne ou un groupe d’un espace, d’une activité, d’un droit ou d’une ressource. L’exclusion peut être juridique, économique, sociale, culturelle ou symbolique. Elle se distingue d’un simple désaccord par le fait qu’elle empêche ou limite la participation à un espace ou à une ressource.","injustice":"Situation ou décision perçue comme contraire à l’équité, au droit ou au principe de traitement juste. Le mot peut désigner une atteinte à une règle de droit comme un sentiment d’iniquité. En philosophie politique, il renvoie aussi aux critères permettant de juger une distribution comme juste ou injuste.","inégalité":"Différence de situation, de droits, de ressources ou de pouvoir entre personnes ou groupes. Une inégalité décrit une différence mesurable ou reconnue ; elle n’est pas automatiquement une injustice. L’analyse politique cherche notamment à distinguer les différences de situation des inégalités de droits ou de chances.","intolérance":"Refus d’accepter certaines opinions, pratiques, identités ou croyances différentes des siennes. Elle se manifeste lorsque la différence est refusée plutôt que simplement contestée. Dans une société pluraliste, la tolérance n’implique pas d’approuver toutes les opinions, mais d’accepter leur coexistence dans les limites du droit.","rejet":"Action ou attitude consistant à refuser, écarter ou ne pas reconnaître une personne, une idée ou un groupe. Le rejet peut être personnel, collectif ou institutionnel. Il devient un phénomène social plus large lorsqu’il prive durablement un groupe de reconnaissance, de relations ou d’accès à certains espaces.","marginalisation":"Processus par lequel une personne ou un groupe est relégué à la périphérie de la vie sociale, économique ou politique. La marginalisation est un processus plutôt qu’un simple événement ponctuel. Elle peut résulter de mécanismes économiques, sociaux, culturels ou politiques qui éloignent durablement un groupe du centre de la vie collective.","harcèlement":"Comportements répétés ou insistants qui dégradent les conditions de vie, de travail ou de sécurité d’une personne. La répétition et l’effet sur la personne sont centraux dans la notion. Selon le contexte, il peut être moral, sexuel, scolaire, professionnel ou en ligne.","violence":"Usage de la force, de la contrainte ou de la menace causant ou visant à causer un dommage physique, psychologique, sexuel, matériel ou social. La violence ne se limite pas à la force physique : elle peut être psychologique, sexuelle, économique, symbolique ou institutionnelle. La qualification juridique dépend ensuite des faits et du droit applicable.","haine":"Hostilité intense envers une personne ou un groupe, pouvant s’exprimer par des paroles, discriminations ou violences. La haine peut rester une attitude intérieure, mais l’expression publique de la haine peut devenir un objet juridique lorsqu’elle prend la forme de menaces, d’incitation ou de discrimination.","exclusion sociale":"Processus par lequel des personnes sont durablement empêchées de participer pleinement à la vie sociale, économique ou civique. Elle peut affecter simultanément l’emploi, le logement, l’éducation, la participation politique ou les relations sociales. La notion insiste sur le caractère cumulatif et durable des obstacles.","ségrégation":"Organisation ou pratique qui sépare durablement des groupes de population, notamment selon l’origine, la couleur de peau, la religion ou le statut. La ségrégation peut être imposée par la loi, organisée par des institutions ou résulter de pratiques sociales durables. Le terme est notamment utilisé pour décrire des séparations fondées sur l’origine ou la couleur de peau.","égalité":"Principe selon lequel les personnes doivent bénéficier des mêmes droits et d’une égale considération devant la loi et les institutions. L’égalité juridique signifie que les mêmes règles fondamentales s’appliquent aux personnes placées dans des situations comparables. Elle n’exclut pas des différences de traitement lorsqu’elles reposent sur un motif juridiquement pertinent.","diversité":"Présence et reconnaissance d’une pluralité d’origines, de cultures, d’identités, d’expériences ou de situations. La diversité peut désigner une pluralité de profils dans une population ou une organisation. Elle ne garantit pas à elle seule l’égalité ou l’inclusion : les trois notions répondent à des questions différentes.","inclusion":"Action visant à permettre à chacun de participer pleinement à la vie sociale et aux institutions, en tenant compte des différences et des besoins. L’inclusion cherche à adapter les environnements pour permettre la participation effective. Elle va donc plus loin que la seule présence d’une personne dans un groupe.","respect":"Reconnaissance de la dignité, des droits et des limites d’autrui. Le respect peut être moral, social ou juridique. Il implique notamment de prendre en compte les droits, l’intégrité et l’autonomie d’autrui.","tolérance":"Acceptation de la coexistence de différences d’opinions, de croyances ou de modes de vie, dans les limites du droit. La tolérance suppose l’acceptation de la coexistence malgré un désaccord. Elle n’oblige pas à considérer toutes les pratiques comme acceptables : le droit fixe des limites.","dignité":"Principe selon lequel toute personne possède une valeur propre qui impose de la respecter et de la traiter humainement. La dignité sert notamment de principe juridique et éthique pour interdire certains traitements dégradants. Elle est attachée à la personne elle-même, indépendamment de son statut social.","solidarité":"Principe ou pratique de soutien réciproque entre personnes ou groupes, notamment face aux difficultés. Elle peut être volontaire, associative ou institutionnalisée par la protection sociale. Elle exprime l’idée qu’une communauté accepte des mécanismes de soutien réciproque.","justice":"Ensemble des institutions et procédures chargées de dire le droit et de trancher les litiges ; le terme désigne aussi le principe d’équité. La justice désigne à la fois une institution, une fonction de jugement et un idéal d’équité. Les tribunaux rendent des décisions selon des règles de procédure et de droit.","droits":"Prérogatives ou libertés reconnues à une personne ou à un groupe par le droit. Un droit peut être individuel ou collectif et être garanti par la loi, la Constitution ou des engagements internationaux. Il peut être accompagné de limites ou de devoirs nécessaires à la protection d’autres droits.","citoyenneté":"Statut juridique et politique d’une personne qui participe à la communauté civique et bénéficie de droits et devoirs. Elle combine généralement des droits politiques, des libertés et des devoirs civiques. Son contenu varie selon les régimes et les conditions d’accès à la nationalité.","religion":"Ensemble de croyances, pratiques, rites et institutions liés au sacré ou au spirituel. Une religion peut comprendre une doctrine, des rites, des prescriptions morales, des communautés et des institutions. Le terme peut aussi désigner la pratique personnelle de la foi.","handicap":"Situation résultant de l’interaction entre une limitation durable et des obstacles qui peuvent restreindre la participation à la société. Les approches contemporaines insistent sur l’interaction entre caractéristiques de la personne et environnement. Les obstacles architecturaux, sociaux ou organisationnels peuvent ainsi transformer une limitation en situation de handicap.","orientation sexuelle":"Attirance affective, romantique ou sexuelle d’une personne, notamment envers des personnes d’un autre, du même ou de plusieurs sexes. Elle ne doit pas être confondue avec l’identité de genre. Le terme décrit principalement la direction des attirances affectives ou sexuelles.","Politique":"Activités liées à l’exercice, à la conquête, à l’organisation et à la contestation du pouvoir dans une société. La politique concerne les rapports de pouvoir, la décision collective et les institutions qui organisent la vie publique. Elle peut désigner une activité, une doctrine, un programme ou une politique publique particulière.","démocratie":"Régime dans lequel la souveraineté politique appartient au peuple, directement ou par l’intermédiaire de représentants. Le concept peut être direct ou représentatif et suppose différents mécanismes de participation et de contrôle. Larousse rappelle le lien avec la souveraineté populaire et le respect des libertés publiques.","république":"Régime politique dans lequel le pouvoir n’est pas fondé sur une succession monarchique et s’exerce au nom de la collectivité publique. Une république peut être démocratique, aristocratique ou populaire : la notion ne garantit donc pas à elle seule la démocratie. Larousse souligne l’opposition historique entre république et monarchie ainsi que la distinction entre les deux concepts.","monarchie":"Régime dans lequel la fonction de chef de l’État est généralement héréditaire, même si ses pouvoirs peuvent être limités par une constitution. Une monarchie peut être absolue, constitutionnelle ou parlementaire. Le fait qu’un monarque soit chef de l’État ne signifie donc pas nécessairement qu’il exerce seul le pouvoir politique.","État":"Organisation politique et juridique exerçant une autorité souveraine sur un territoire et une population. Larousse distingue l’État comme société politique organisée sur un territoire et l’État comme ensemble des pouvoirs publics. Sa souveraineté est interne et externe, sous réserve des engagements juridiques qu’il accepte.","nation":"Communauté humaine se percevant comme un ensemble politique ou historique partagé, souvent associé à un territoire et à une identité collective. La nation peut être pensée comme une communauté historique, culturelle ou politique. Elle ne se confond pas nécessairement avec l’État : une nation peut exister sans disposer d’un État souverain.","citoyen":"Personne reconnue comme membre d’une communauté politique et titulaire de droits et devoirs civiques. Le citoyen participe à la communauté politique et peut disposer de droits électoraux selon les conditions fixées par le régime. Le terme est distinct de celui de simple résident ou de national selon les contextes juridiques.","constitution":"Texte ou ensemble de règles fondamentales qui organisent les institutions et définissent les grands principes d’un État. Elle organise notamment les institutions, la répartition des compétences et les garanties fondamentales. Elle peut être écrite dans un texte unique ou résulter d’un ensemble de normes constitutionnelles.","souveraineté":"Pouvoir suprême reconnu à un État et, en démocratie, principe selon lequel le pouvoir politique procède du peuple. Pour l’État, elle désigne l’autorité suprême sur le territoire et l’indépendance dans les relations internationales. Dans une démocratie, la souveraineté peut être attribuée au peuple ou à la nation et être exercée par des représentants ou par référendum.","élection":"Procédure par laquelle des électeurs choisissent une ou plusieurs personnes pour exercer un mandat. Une élection peut être directe ou indirecte, uninominale ou de liste, majoritaire ou proportionnelle selon le système retenu. Elle sert à désigner des représentants ou, dans certains régimes, des titulaires de fonctions exécutives.","vote":"Expression d’un choix politique ou civique lors d’une consultation, d’une élection ou d’un référendum. Le vote est l’acte par lequel une personne exprime un choix lors d’une consultation. Il peut être secret et ses modalités dépendent de la nature du scrutin.","gouvernement":"Organe exécutif chargé de conduire la politique d’un État et d’administrer les affaires publiques. Dans le vocabulaire institutionnel, le gouvernement est l’organe qui exerce le pouvoir exécutif. Il peut comprendre un chef du gouvernement et des ministres, avec des pouvoirs variables selon la Constitution.","président":"Titre d’un dirigeant placé à la tête d’une institution, notamment de l’État dans une république présidentielle ou semi-présidentielle. Le titre signifie littéralement celui qui préside, mais il désigne notamment le chef de l’État dans les républiques. Ses compétences dépendent du régime : présidentiel, semi-présidentiel ou parlementaire.","Premier ministre":"Chef du gouvernement dans les systèmes qui distinguent cette fonction de celle du chef de l’État. Dans les régimes qui connaissent cette fonction, il coordonne l’action du gouvernement. Son rôle et son autonomie par rapport au chef de l’État varient selon le système constitutionnel.","Parlement":"Institution législative, généralement composée d’une ou plusieurs chambres, qui débat et vote les lois et contrôle l’exécutif selon le régime. Le Parlement exerce principalement la fonction législative et peut aussi contrôler l’exécutif. Il peut être monocaméral ou bicaméral.","député":"Membre élu d’une assemblée représentant les citoyens, notamment de l’Assemblée nationale en France. En France, le député siège à l’Assemblée nationale. Il participe au vote de la loi, au contrôle du Gouvernement et à l’évaluation des politiques publiques.","sénateur":"Membre élu d’une chambre haute représentant les collectivités ou la nation selon le système politique ; en France, membre du Sénat. En France, le sénateur siège au Sénat et participe à la fonction législative. Le Sénat représente notamment les collectivités territoriales et ses membres sont élus au suffrage indirect.","loi":"Règle juridique adoptée selon une procédure législative et s’imposant aux personnes dans son champ d’application. La loi appartient à la hiérarchie des normes et doit respecter les normes qui lui sont supérieures. En France, elle est votée par le Parlement selon la procédure prévue par la Constitution.","pouvoir exécutif":"Pouvoir chargé de mettre en œuvre les lois et de conduire l’action gouvernementale. Il comprend généralement le chef de l’État et le gouvernement selon le régime. Il assure la mise en œuvre des lois et la conduite de l’administration et des politiques publiques.","pouvoir législatif":"Pouvoir chargé de discuter, adopter et modifier les lois. Il est exercé par une assemblée ou un Parlement selon les constitutions. Ses fonctions peuvent inclure l’initiative, la discussion, l’adoption et la modification des lois.","pouvoir judiciaire":"Fonction consistant à juger les litiges et infractions selon le droit, avec des garanties d’indépendance selon les systèmes. Il désigne la fonction de juger les litiges et infractions. Dans un État de droit, son indépendance et les garanties d’un procès équitable sont essentielles.","séparation des pouvoirs":"Principe d’organisation qui distingue les fonctions exécutive, législative et judiciaire afin de limiter leur concentration. La séparation vise à éviter qu’une même autorité concentre toutes les fonctions de décision, d’exécution et de jugement. Dans la pratique, les régimes combinent souvent séparation et mécanismes de contrôle réciproque.","parti politique":"Organisation de personnes partageant des orientations politiques et cherchant à influencer ou exercer le pouvoir. Un parti peut présenter des candidats, élaborer des programmes, mobiliser des électeurs et participer au gouvernement ou à l’opposition. Les systèmes multipartites organisent la compétition entre plusieurs partis.","impérialisme":"Politique d’expansion et de domination d’un État sur d’autres territoires ou peuples, par des moyens politiques, économiques ou militaires. Le terme est utilisé pour décrire une logique d’expansion et de domination au-delà des frontières. Il peut concerner l’occupation territoriale mais aussi des formes de dépendance économique ou politique.","opposition":"Ensemble des acteurs politiques qui ne soutiennent pas le gouvernement au pouvoir et contestent tout ou partie de sa politique. L’opposition participe au débat politique en contestant le gouvernement et en proposant des alternatives. Dans un régime pluraliste, son existence contribue au contrôle du pouvoir.","sionisme":"Mouvement politique moderne visant à l’établissement et au maintien d’un foyer national juif en Palestine historique, devenu un courant politique aux formes diverses. Le terme désigne historiquement un mouvement né à la fin du XIXe siècle autour de la constitution d’un État juif en Palestine. Le sionisme a ensuite pris des formes politiques diverses ; il faut distinguer le terme du judaïsme en tant que religion.","prosélytisme":"Action visant à convaincre d’autres personnes d’adopter une religion, une doctrine ou, par extension, une cause. Le mot implique une démarche active visant à convaincre ou convertir. Il peut être religieux, mais aussi s’employer par extension pour une doctrine ou une cause.","majorité":"Dans une décision collective, part ou ensemble qui obtient le plus de voix ou dépasse le seuil requis pour décider. La majorité peut être absolue, relative ou qualifiée selon la règle du vote. En politique, elle peut désigner le groupe disposant du plus grand nombre de sièges ou la majorité requise pour adopter une décision.","gauche":"Famille de courants politiques généralement associés à l’égalité sociale, à la protection sociale et à un rôle plus important de l’action publique, avec une grande diversité interne. Le terme vient historiquement de la place occupée à gauche dans certaines assemblées parlementaires. Son contenu a évolué et recouvre aujourd’hui des familles très différentes, de la social-démocratie aux courants révolutionnaires.","droite":"Famille de courants politiques généralement associés à l’ordre, à la continuité institutionnelle, à la propriété ou à des conceptions sociales plus conservatrices, avec une grande diversité interne. Le terme est également issu de la disposition des groupes parlementaires. Il peut désigner des courants conservateurs, libéraux, nationalistes ou d’autres familles selon les périodes et les pays.","extrême gauche":"Ensemble de courants situés à la gauche radicale de l’échiquier politique, souvent favorables à des transformations profondes de l’ordre économique et social. L’expression regroupe des courants très différents, parfois révolutionnaires ou anticapitalistes. Elle ne correspond pas à une doctrine unique et son usage peut varier selon les pays et les contextes.","extrême droite":"Ensemble de courants situés à la droite radicale, souvent marqués par un nationalisme fort, une conception restrictive de l’appartenance politique et un rejet de certains principes du pluralisme libéral. L’expression désigne des courants situés à la droite radicale de l’échiquier politique. Selon les mouvements, elle peut être associée au nationalisme radical, à l’autoritarisme ou à diverses conceptions restrictives de l’appartenance nationale.","libéralisme":"Courant de pensée mettant l’accent sur les libertés individuelles, l’État de droit, les droits civils et, selon les variantes, l’économie de marché. Le libéralisme politique met l’accent sur les libertés individuelles, les droits et les limites du pouvoir. Le libéralisme économique désigne plus spécifiquement des doctrines favorables à une large place accordée au marché, avec de fortes variations selon les auteurs.","socialisme":"Famille de doctrines favorisant une plus grande égalité économique et sociale et une intervention collective dans l’économie, selon des formes variées. Le socialisme regroupe des traditions réformistes et révolutionnaires. Un trait commun est la recherche d’une plus grande égalité et d’une organisation collective de l’économie, mais les moyens proposés diffèrent largement.","communisme":"Famille de doctrines visant une société sans classes et la mise en commun des principaux moyens de production ; les régimes qui s’en sont réclamés ont pris des formes historiques diverses. Dans la théorie marxiste, il vise à dépasser la division en classes et la propriété privée des principaux moyens de production. Les régimes historiques qui se sont réclamés du communisme ont adopté des institutions et des politiques très diverses.","nationalisme":"Doctrine ou mouvement plaçant la nation et sa souveraineté au centre de la vie politique. Le nationalisme fait de la nation un principe central de légitimité politique. Il peut prendre des formes civiques, culturelles, indépendantistes ou plus exclusives selon les mouvements.","populisme":"Style ou courant politique opposant le « peuple » à des élites jugées séparées de lui ; le terme recouvre des mouvements idéologiquement très différents. Le mot est utilisé pour des mouvements de gauche, de droite ou transversaux. Son élément récurrent est l’opposition entre un peuple présenté comme homogène et des élites jugées éloignées de ses intérêts.","laïcité":"Principe d’organisation des pouvoirs publics fondé notamment sur la neutralité de l’État à l’égard des cultes et la liberté de conscience ; en France, il est associé à la loi de 1905 et à la Constitution. En France, elle est liée à la liberté de conscience, à la neutralité des pouvoirs publics et à l’égalité des citoyens quelle que soit leur religion ou leur absence de religion. Elle ne signifie pas l’interdiction des convictions religieuses dans la société.","liberté d’expression":"Droit de communiquer des opinions et des informations, soumis aux limites prévues par la loi, notamment pour protéger les personnes et l’ordre public. Elle protège la possibilité de communiquer des opinions et des informations. Elle connaît cependant des limites légales, notamment concernant la diffamation, les menaces, l’incitation à la haine ou la protection de la vie privée.","liberté":"Faculté de choisir et d’agir sans contrainte arbitraire, dans les limites nécessaires à la coexistence avec les droits d’autrui et la loi. La liberté politique et civile implique l’absence de contraintes arbitraires. En droit, elle s’exerce dans un cadre qui doit aussi protéger les libertés et la sécurité d’autrui.","fraternité":"Principe de solidarité et de communauté entre les membres d’une société ; en France, l’un des termes de la devise républicaine. Dans la devise républicaine, la fraternité exprime une exigence de solidarité entre membres de la communauté politique. Le terme possède aussi un sens plus large de lien humain et de soutien réciproque.","État de droit":"Principe selon lequel les pouvoirs publics eux-mêmes sont soumis au droit, sous le contrôle de normes et de juridictions. Le principe signifie que personne, y compris l’État et ses dirigeants, n’est au-dessus du droit. Il suppose des règles accessibles, des juridictions effectives et des garanties contre l’arbitraire.","référendum":"Procédure permettant au corps électoral de se prononcer directement sur une question ou un texte. Il peut porter sur une loi, une question institutionnelle ou d’autres décisions selon la Constitution. Il relève de la démocratie directe ou semi-directe et se distingue d’une élection qui choisit une personne ou une liste.","abstention":"Fait de ne pas participer à un vote alors que l’on dispose du droit de voter. L’abstention n’est pas la même chose qu’un vote blanc ou nul : elle consiste à ne pas participer au scrutin. Son niveau peut être interprété comme un indice de mobilisation ou de distance politique, mais sa signification dépend du contexte.","propagande":"Communication organisée visant à influencer fortement les opinions ou comportements, souvent en sélectionnant ou orientant l’information. La propagande cherche généralement à orienter les perceptions de manière organisée. Elle peut utiliser des informations vraies, fausses ou sélectionnées de façon orientée.","oppression":"Exercice durable d’un pouvoir qui prive ou restreint fortement les libertés et les droits d’un groupe. L’oppression suppose une asymétrie durable de pouvoir et une restriction des possibilités d’un groupe. Elle peut être politique, économique, sociale ou culturelle.","dictature":"Régime dans lequel le pouvoir est concentré entre les mains d’un dirigeant ou d’un groupe sans véritable concurrence politique libre. Elle peut être personnelle, militaire ou exercée par un parti unique. L’absence de concurrence politique libre et de contrôles effectifs du pouvoir est un trait central de la notion.","autoritarisme":"Mode de gouvernement privilégiant la concentration du pouvoir et limitant fortement le pluralisme et certaines libertés politiques. Un régime autoritaire limite généralement le pluralisme politique tout en pouvant conserver certaines institutions formelles. Il se distingue de la démocratie par l’affaiblissement des mécanismes de contrôle et de contestation du pouvoir.","droits de l’homme":"Ensemble de droits et libertés fondamentaux reconnus à toute personne en raison de sa qualité d’être humain. Ils comprennent notamment les libertés civiles, les droits politiques et des protections liées à la dignité de la personne. Leur reconnaissance internationale s’appuie sur des textes comme la Déclaration de 1948.","diplomatie":"Ensemble des pratiques et négociations par lesquelles les États et autres acteurs conduisent leurs relations extérieures. Elle peut passer par des négociations, des représentations permanentes, des accords et des médiations. Les diplomates cherchent à défendre les intérêts de leur État tout en maintenant des relations officielles.","mondialisation":"Processus d’intensification des échanges, flux et interdépendances entre les différentes parties du monde. Elle concerne les échanges commerciaux mais aussi les flux financiers, les communications, les migrations et la circulation des techniques. Elle renforce les interdépendances sans faire disparaître les États.","pédéraste":"Terme historique et aujourd’hui péjoratif désignant un homme ayant des relations sexuelles avec des garçons adolescents ; il renvoie aussi à des pratiques spécifiques de la Grèce antique. Le terme est ancien et péjoratif dans l’usage contemporain. Il ne doit pas être employé comme une étiquette juridique : son sens historique doit être replacé dans les contextes antiques ou dans l’histoire des catégories sexuelles.","éphébophile":"Terme de sexologie désignant l’attirance sexuelle d’un adulte envers des adolescents pubères ; ce terme ne constitue pas une qualification juridique. Le terme est utilisé pour décrire une attirance sexuelle envers des adolescents pubères, notamment dans une littérature sexologique. Il s’agit d’une notion descriptive et non d’une catégorie pénale en elle-même ; la légalité d’un acte dépend de l’âge, du consentement et du droit applicable.","Moyen Âge":"Période historique de l’Europe située, dans le découpage traditionnel, entre l’Antiquité et les Temps modernes, généralement du Ve au XVe siècle. Elle est marquée par la diversité des pouvoirs, le développement de sociétés chrétiennes, des échanges commerciaux, des seigneuries et des royaumes.","chevalier":"Combattant à cheval appartenant à une élite guerrière de la société médiévale, progressivement associée à des règles de conduite et à un statut social. Le terme recouvre des réalités différentes selon les périodes.","château":"Résidence fortifiée ou seigneuriale destinée à l’habitation, à la défense et à l’exercice du pouvoir local. Les formes du château évoluent fortement entre le haut et le bas Moyen Âge.","seigneur":"Personne exerçant des droits de commandement, de justice ou de prélèvement sur un territoire ou une population dans le cadre de la société seigneuriale.","roi":"Souverain d’un royaume. Selon les périodes, son pouvoir peut être limité par les coutumes, les privilèges, les institutions ou, à l’inverse, fortement centralisé.","reine":"Femme qui exerce la souveraineté d’un royaume ou épouse d’un roi. Selon les monarchies et les périodes, une reine peut être souveraine en titre ou participer au pouvoir par la régence et la représentation.","chevalerie":"Institution et idéal social associés aux chevaliers. La chevalerie comprend des pratiques guerrières, un statut, des cérémonies et, dans les représentations médiévales, des valeurs telles que la prouesse et la loyauté.","féodalité":"Terme historiographique désignant un ensemble de relations sociales et politiques fondées notamment sur les liens personnels, les fiefs et les obligations entre seigneurs et vassaux. Le mot ne correspond pas à un système identique dans toute l’Europe médiévale.","seigneurie":"Ensemble des terres, droits et pouvoirs qu’un seigneur exerce sur un territoire et sur ses habitants. Elle constitue une structure majeure de l’organisation rurale médiévale.","vassal":"Personne liée à un seigneur par un engagement personnel de fidélité et de service, en échange notamment d’une protection ou d’un bénéfice. Le rapport vassalique repose sur des obligations réciproques.","suzerain":"Seigneur dont dépend un vassal dans une relation féodo-vassalique. Le terme désigne un supérieur dans cette relation sans impliquer qu’il exerce nécessairement un pouvoir direct sur tous les habitants du territoire.","paysan":"Personne vivant principalement de l’agriculture et du travail de la terre. Dans les sociétés médiévales, les paysans présentent des situations juridiques et économiques très diverses.","serf":"Personne juridiquement dépendante d’un seigneur dans certaines sociétés médiévales. Le servage limite la liberté de déplacement et impose diverses obligations, sans être identique à l’esclavage.","village":"Ensemble d’habitations formant une communauté locale, généralement plus importante qu’un simple hameau et liée à des activités agricoles, artisanales ou commerciales.","royaume":"Territoire gouverné par un roi ou une reine. Le royaume est à la fois un espace politique et, selon les époques, un ensemble de droits, institutions et territoires liés à la Couronne.","noblesse":"Ordre social historiquement privilégié composé de familles bénéficiant de statuts, titres, droits ou obligations particuliers. La noblesse n’est pas homogène et ses privilèges varient selon les lieux et les périodes.","clergé":"Ensemble des personnes investies d’une fonction religieuse dans une Église, notamment les membres ordonnés. Dans la société d’Ancien Régime, le clergé constitue également un ordre doté de statuts particuliers.","Église":"Institution religieuse organisée autour d’une communauté de croyants, d’un clergé et de règles de culte. En histoire européenne, le terme désigne souvent l’institution chrétienne dans son rôle religieux et social.","prêtre":"Ministre du culte chrétien ayant reçu l’ordination sacerdotale. Dans l’Église catholique, il célèbre notamment la messe et administre certains sacrements.","moine":"Religieux vivant selon une règle communautaire ou un mode de vie monastique consacré à la prière, au travail et à la vie spirituelle.","abbaye":"Établissement monastique dirigé par un abbé ou une abbesse, comprenant généralement une communauté religieuse et des bâtiments dédiés au culte, à la vie collective et à l’administration.","cathédrale":"Église principale d’un diocèse, où se trouve la cathèdre, siège symbolique de l’évêque. Les cathédrales sont souvent d’importants monuments architecturaux.","croisade":"Expédition militaire menée dans un cadre religieux sous l’impulsion ou avec l’approbation de l’Église latine, particulièrement entre les XIe et XIIIe siècles. Le terme est principalement associé aux expéditions vers le Proche-Orient mais s’applique aussi à d’autres conflits.","pèlerinage":"Voyage entrepris vers un lieu considéré comme sacré ou particulièrement important pour des raisons religieuses ou spirituelles.","bataille":"Affrontement militaire organisé entre deux forces ou groupes armés dans un espace et une période déterminés.","épée":"Arme blanche à lame généralement longue et destinée principalement au combat rapproché. Ses formes et ses usages ont beaucoup varié selon les périodes.","armure":"Ensemble de protections portées par un combattant pour réduire les effets des armes. Les armures médiévales évoluent de la cotte de mailles aux armures de plates plus complètes.","donjon":"Tour ou bâtiment fortifié principal d’un château médiéval, pouvant servir de résidence, de refuge et de poste de défense.","remparts":"Ensemble de fortifications entourant et protégeant une ville, un château ou un autre lieu stratégique.","tournoi":"Affrontement codifié entre chevaliers, organisé comme un exercice militaire, un spectacle et un événement social dans l’Europe médiévale.","cheval":"Animal domestique utilisé notamment pour le transport, l’agriculture et la guerre. Le cheval joue un rôle majeur dans les sociétés médiévales et dans la mobilité des élites guerrières.","agriculture":"Ensemble des activités de culture des végétaux et d’élevage des animaux destinées notamment à produire des aliments, des matières premières ou à faire vivre une population.","commerce":"Échange de biens ou de services entre personnes, entreprises ou territoires. Le commerce peut être local, régional ou international.","marché":"Lieu ou système où se rencontrent une offre et une demande de biens ou de services, avec des échanges organisés selon des règles et des prix.","artisan":"Personne qui exerce un métier manuel ou technique en produisant, transformant ou réparant des objets et des biens, souvent dans une petite entreprise ou un atelier.","marchand":"Personne ou entreprise qui achète et revend des marchandises dans le but de réaliser une activité commerciale.","guilde":"Association professionnelle regroupant historiquement des artisans ou commerçants d’un même métier afin de défendre leurs intérêts, fixer certaines règles et organiser la profession.","bourgeois":"Membre des catégories urbaines vivant du commerce, de l’artisanat, de la finance ou des fonctions administratives. Le terme a des significations sociales différentes selon les périodes.","ville":"Agglomération caractérisée par une concentration importante d’habitants, d’activités, de services et d’institutions. Dans l’histoire, les villes sont des centres politiques, économiques et culturels.","famine":"Situation de pénurie alimentaire grave et étendue provoquant une forte hausse de la mortalité et une dégradation des conditions de vie.","épidémie":"Propagation rapide d’une maladie dans une population ou une région pendant une période donnée. Une épidémie se distingue par son extension par rapport au niveau habituel.","peste":"Maladie infectieuse causée par la bactérie Yersinia pestis, responsable notamment de la peste bubonique. Elle a provoqué plusieurs épidémies majeures dans l’histoire, dont la peste noire du XIVe siècle.","château-fort":"Château conçu principalement pour la défense, comprenant des ouvrages fortifiés tels que murailles, tours, fossés et portes protégées.","manuscrit":"Texte écrit ou copié à la main avant ou en parallèle de l’essor de l’imprimerie. Les manuscrits médiévaux peuvent être religieux, juridiques, littéraires ou administratifs.","enluminure":"Décoration peinte ou dorée d’un manuscrit, comprenant des lettres ornées, motifs, scènes figurées ou bordures.","troubadour":"Poète et musicien de langue d’oc, actif principalement dans les cours et milieux aristocratiques du sud de l’Europe médiévale.","littérature":"Ensemble des œuvres écrites ou orales à visée artistique, esthétique, narrative ou poétique, ainsi que l’étude de ces œuvres.","féodal":"Qui se rapporte à la féodalité, aux relations de vassalité, aux fiefs ou à la société seigneuriale médiévale.","Guerre":"Conflit armé entre États, groupes organisés ou communautés. Une guerre peut être limitée ou générale, intérieure ou internationale, et prendre différentes formes.","géopolitique":"Étude des relations de pouvoir entre acteurs politiques en fonction notamment des territoires, des ressources, des frontières et des rapports de puissance.","conflit":"Opposition ou affrontement entre deux ou plusieurs acteurs dont les intérêts, objectifs ou valeurs sont incompatibles. Un conflit peut être politique, social, économique ou militaire.","paix":"Situation dans laquelle cesse la guerre ou dans laquelle les relations entre groupes ou États sont caractérisées par l’absence de conflit armé.","armée":"Ensemble organisé de forces militaires relevant d’un État ou d’une autorité politique et chargé notamment de la défense et des opérations armées.","soldat":"Personne appartenant à une force armée et participant aux missions militaires de celle-ci.","militaire":"Qui concerne les forces armées, la guerre ou la défense. Le terme peut aussi désigner une personne servant dans une armée.","invasion":"Entrée massive et généralement hostile de forces armées sur le territoire d’un autre État ou groupe.","occupation":"Contrôle effectif et durable d’un territoire par une force étrangère ou par une autorité qui ne dispose pas nécessairement d’une souveraineté reconnue.","défense":"Ensemble des moyens et actions destinés à protéger un territoire, une population ou des intérêts contre une menace ou une attaque.","attaque":"Action offensive dirigée contre une personne, une position, un territoire ou une force adverse.","frontière":"Limite politique ou juridique séparant deux territoires, notamment deux États. Elle peut être terrestre, maritime ou parfois conventionnelle.","territoire":"Espace géographique soumis à l’autorité ou à la juridiction d’un pouvoir politique ou occupé par une population.","puissance":"Capacité d’un acteur à influencer les comportements, décisions ou rapports de force dans un domaine donné. En géopolitique, elle peut être militaire, économique, diplomatique, technologique ou culturelle.","alliance":"Accord ou association entre États ou autres acteurs visant à coordonner leurs actions ou à se soutenir face à des intérêts ou menaces communs.","négociation":"Processus de discussion entre plusieurs parties cherchant à parvenir à un accord ou à réduire leur désaccord.","traité":"Accord formel conclu entre des États ou autres sujets de droit international, généralement écrit et destiné à produire des effets juridiques.","cessez-le-feu":"Accord ou décision ordonnant la suspension des combats, temporairement ou durablement, sans mettre nécessairement fin au conflit politique.","armistice":"Convention par laquelle des parties à un conflit suspendent officiellement les hostilités, souvent pour permettre des négociations ou préparer un règlement.","guerre civile":"Conflit armé opposant des groupes organisés au sein d’un même État ou d’un même espace politique.","guerre mondiale":"Guerre impliquant directement ou indirectement un très grand nombre de puissances et de territoires sur plusieurs régions du monde.","guerre froide":"Période de rivalité géopolitique entre les États-Unis et l’Union soviétique, principalement de la fin des années 1940 au début des années 1990, sans affrontement militaire direct généralisé entre les deux superpuissances.","terrorisme":"Recours à la violence ou à la menace de violence, notamment contre des civils, dans le but de provoquer la peur et d’influencer un public ou un pouvoir politique. Les définitions juridiques varient selon les États.","guérilla":"Forme de lutte armée menée par des groupes généralement plus faibles que l’adversaire, utilisant la mobilité, la surprise et des actions de harcèlement.","stratégie":"Art de concevoir et de coordonner des actions à long terme pour atteindre un objectif politique ou militaire.","tactique":"Organisation et conduite des actions à l’échelle d’une opération ou d’un engagement particulier, notamment militaire.","armement":"Ensemble des armes, équipements et systèmes militaires utilisés par une force armée.","missile":"Engin autopropulsé destiné à atteindre une cible à distance, généralement guidé ou conçu selon une trajectoire déterminée.","drone":"Aéronef ou système télépiloté ou autonome, généralement sans pilote humain à bord. Il peut être utilisé à des fins civiles, de renseignement ou militaires.","nucléaire":"Qui se rapporte au noyau de l’atome. Dans les relations internationales, le terme renvoie notamment aux armes nucléaires et à la dissuasion fondée sur leur possession.","renseignement":"Ensemble d’informations recueillies, vérifiées et analysées afin d’éclairer une décision, notamment politique ou militaire.","espionnage":"Recherche clandestine d’informations confidentielles appartenant à un adversaire, une organisation ou un État.","sanctions":"Mesures de pression prises par un État, un groupe d’États ou une organisation contre un acteur afin de modifier son comportement. Elles peuvent être économiques, diplomatiques, financières ou individuelles.","embargo":"Interdiction ou forte restriction imposée sur l’exportation, l’importation ou l’échange de certains biens avec un pays ou un acteur donné.","réfugié":"Personne qui a quitté son pays en raison de persécutions ou de graves menaces et qui bénéficie, lorsqu’elle remplit les conditions légales, d’une protection internationale.","déplacement":"Mouvement de personnes d’un lieu à un autre. En contexte de crise, le terme peut désigner le déplacement forcé de populations à l’intérieur d’un pays ou vers un autre territoire.","empire":"Ensemble politique composé de plusieurs territoires ou peuples soumis à l’autorité d’un même pouvoir impérial.","colonisation":"Processus par lequel un État ou un groupe établit et maintient son contrôle sur un territoire et sa population, souvent en y installant des colons et en imposant des structures de domination.","influence":"Capacité d’un acteur à modifier ou orienter les décisions, comportements ou perceptions d’autres acteurs sans exercer nécessairement un contrôle direct.","ressources":"Ensemble des moyens disponibles et exploitables, notamment naturels, économiques, énergétiques, humains ou stratégiques.","pétrole":"Hydrocarbure liquide naturel extrait du sous-sol et utilisé notamment pour produire des carburants, des lubrifiants, de l’énergie et de nombreux produits industriels.","coopération":"Action de travailler ensemble pour atteindre un objectif commun ou coordonner des politiques et des ressources.","ONU":"Organisation internationale créée en 1945 pour favoriser la paix, la sécurité internationale, la coopération entre États et le développement du droit international.","OTAN":"Organisation politico-militaire créée en 1949 fondée sur un principe de défense collective entre ses membres. Son objectif central est la sécurité de l’Alliance face aux menaces communes.","Union européenne":"Organisation politique et économique réunissant des États européens autour d’institutions communes, d’un marché intérieur et de politiques partagées.","G7":"Forum réunissant sept grandes économies démocratiques occidentales et le représentant de l’Union européenne pour discuter de grands enjeux économiques et internationaux.","G20":"Forum international réunissant les principales économies mondiales afin de coordonner des positions sur les questions économiques et financières et d’autres enjeux globaux.","BRICS":"Groupe de coopération réunissant à l’origine le Brésil, la Russie, l’Inde, la Chine et l’Afrique du Sud, élargi à d’autres États, visant notamment à renforcer leur coopération économique et leur poids diplomatique.","OMC":"Organisation mondiale du commerce chargée notamment de favoriser et encadrer les échanges internationaux et de fournir un cadre de règlement des différends commerciaux.","FMI":"Fonds monétaire international, organisation internationale qui surveille le système monétaire international et apporte notamment une aide financière aux pays connaissant de graves difficultés extérieures.","Banque mondiale":"Groupe d’institutions financières internationales qui finance et accompagne notamment des projets de développement et de réduction de la pauvreté."};


/* Extension lexique — entrée plurielle demandée */
if (!DEFINITIONS["croisades"]) DEFINITIONS["croisades"] = "Expéditions militaires et religieuses menées en Occident médiéval, principalement entre les XIe et XIIIe siècles, sous l’impulsion de pouvoirs chrétiens d’Europe occidentale vers le Proche-Orient et d’autres théâtres. Le terme peut désigner l’ensemble du mouvement ou chacune des expéditions prises individuellement.";
if (!DEFINITIONS["frexit"]) DEFINITIONS["frexit"] = "Terme formé à partir de « France » et « exit », désignant le projet de sortie de la France de l’Union européenne. Le mot est généralement employé dans le débat politique pour désigner les courants ou mouvements favorables à cette sortie.";
if (!DEFINITIONS["Fascisme"]) DEFINITIONS["Fascisme"] = "Doctrine et régime politique autoritaire né en Italie autour de Benito Mussolini après la Première Guerre mondiale. Le fascisme italien repose notamment sur le parti unique, l’exaltation nationaliste, le culte du chef, la violence politique et le corporatisme. Le terme est ensuite utilisé, avec prudence, pour d’autres mouvements ou régimes présentant certaines caractéristiques comparables. À ne pas confondre automatiquement avec tout autoritarisme ou avec le totalitarisme. Source principale : Dictionnaire Larousse.";


function hashString(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}

/* Définitions — épingles interactives */
(function initDefinitions(){
  const section=document.getElementById('definitions');
  if(!section) return;
  const title=document.getElementById('definitionTitle');
  const text=document.getElementById('definitionText');
  const category=document.getElementById('definitionCategory');
  const pins=[...section.querySelectorAll('.definition-pin')];
  const cap=s=>{const t=String(s||'');return t ? t.charAt(0).toLocaleUpperCase('fr-FR')+t.slice(1) : t;};
  const definitionIndex=new Map(pins.map(pin=>[pin.dataset.definition,pin]));
  if(!definitionIndex.has('Fascisme')){
    const pin=document.createElement('button');
    pin.className='definition-pin definition-pin-added'; pin.type='button'; pin.dataset.definition='Fascisme'; pin.setAttribute('aria-label','Définition : Fascisme');
    pin.innerHTML='<span class="definition-pin-dot"></span><strong>Fascisme</strong>';
    section.querySelector('.definitions-nebula')?.appendChild(pin);
    pins.push(pin);
  }
  if(!definitionIndex.has('frexit')){
    const pin=document.createElement('button');
    pin.className='definition-pin definition-pin-added'; pin.type='button'; pin.dataset.definition='frexit'; pin.setAttribute('aria-label','Définition : Frexit');
    pin.innerHTML='<span class="definition-pin-dot"></span><strong>Frexit</strong>';
    section.querySelector('.definitions-nebula')?.appendChild(pin);
    pins.push(pin);
  }
  pins.forEach(pin=>{const term=pin.dataset.definition;pin.querySelector('strong')&&(pin.querySelector('strong').textContent=cap(term));pin.setAttribute('aria-label','Définition : '+cap(term));});
  // Tri alphabétique stable, avec accents gérés en français.
  const container=section.querySelector('.definitions-nebula');
  if(container){
    const sorted=[...pins].sort((a,b)=>a.dataset.definition.localeCompare(b.dataset.definition,'fr',{sensitivity:'base'}));
    sorted.forEach(pin=>container.appendChild(pin));
  }
  function select(term){
    const key=Object.keys(DEFINITIONS).find(k=>normalizeSearchText(k)===normalizeSearchText(term))||term;
    const value=DEFINITIONS[key]||'Définition à compléter.';
    title.textContent=key.charAt(0).toLocaleUpperCase('fr-FR')+key.slice(1); text.textContent=value; category.textContent='Lexique LYS · définition';
    pins.forEach(pin=>pin.classList.toggle('is-selected',pin.dataset.definition===term));
    title.classList.remove('definition-pop'); void title.offsetWidth; title.classList.add('definition-pop'); const source=document.getElementById('definitionSource'); if(source){source.innerHTML='<a href="https://www.larousse.fr/dictionnaires/francais" target="_blank" rel="noopener noreferrer">Source principale : Dictionnaire Larousse ↗</a><span>Définition reformulée et contextualisée dans LYS.</span>'; }
  }
  pins.forEach(pin=>{pin.addEventListener('click',()=>select(pin.dataset.definition));pin.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(pin.dataset.definition);}})});
})();


/* Classements — génération des épingles depuis les catégories existantes, drag & drop et sauvegarde locale. */
(function initRankings(){
  const root=document.getElementById('classements'); if(!root) return;
  const tabs=[...root.querySelectorAll('.rank-tab')];
  const panel=root.querySelector('.ranking-panel');
  const source=root.querySelector('.ranking-items-source');
  const tiers=['S','Superbe','Japprouve','Indifferent','Desapprouve','Impossible','Inconnu'];
  const configs={partis:{selector:'#politique .politique-pin.party-pin',kind:'partis',type:'Parti'},personnalites:{selector:'#politique .politique-pin:not(.party-pin)',kind:'personnalites',type:'Personnalité'},rois:{selector:'#souverains .ruler',kind:'rois',type:'Roi'},medias:{selector:'#media .media-logo',kind:'medias',type:'Média'},presidents:{selector:'#presidentsPanel .president-card',kind:'presidents',type:'Président'}};
  const data={};
  let selectedRankItem=null;
  function slug(key,name){return key+'::'+name;}
  function extract(key){
    if(data[key]) return data[key];
    const cfg=configs[key];
    const els=[...document.querySelectorAll(cfg.selector)];
    const seen=new Set();
    data[key]=els.map((el,i)=>{
      const img=el.querySelector('img');
      const name=el.getAttribute('data-politique')||el.getAttribute('title')||el.getAttribute('aria-label')?.replace(/^Ouvrir (la fiche de|la biographie de)\s*/i,'')||el.dataset.ruler||el.querySelector('strong')?.textContent?.trim()||img?.alt||`Élément ${i+1}`;
      if(seen.has(name)) return null; seen.add(name);
      const src=img?.getAttribute('src')||'assets/Lys.png';
      return {id:slug(key,name),name,src,kind:cfg.kind,type:cfg.type,source:el};
    }).filter(Boolean);
    return data[key];
  }
  function allEntries(key){return extract(key)}
  function activeKey(){return root.querySelector('.rank-tab.is-active')?.dataset.ranking||'partis'}
  function storageKey(k){return 'lys-ranking-'+k}
  function read(k){try{const saved=JSON.parse(localStorage.getItem(storageKey(k))||'{}');if(k==='partis'){const defaults={'partis::Nouvelle Énergie':'Inconnu','partis::La France Humaniste':'Inconnu',"partis::LFQV — La France qu'on veut":'Inconnu','partis::France Libre':'Inconnu'};Object.entries(defaults).forEach(([id,tier])=>{if(!saved[id])saved[id]=tier});}return saved}catch{return {}}}
  function write(k,map){localStorage.setItem(storageKey(k),JSON.stringify(map))}
  function makeItem(item){
    const b=document.createElement('button'); b.type='button'; b.className='rank-item'; b.draggable=true; b.dataset.rankId=item.id; b.dataset.kind=item.kind; b.title=`${item.name} — ${item.type}`; b.setAttribute('aria-label',`Classer ${item.name}`);
    const im=document.createElement('img'); im.src=item.src; im.alt=item.name; im.loading='lazy';
    const name=document.createElement('span'); name.className='rank-item-name'; name.textContent=item.name;
    const typ=document.createElement('span'); typ.className='rank-item-type'; typ.textContent=item.type;
    b.append(im,name,typ); return b;
  }
  function render(key){
    selectedRankItem=null;
    panel.querySelectorAll('.rank-item.is-rank-selected').forEach(x=>x.classList.remove('is-rank-selected'));
    panel.querySelectorAll('.tier-items').forEach(x=>x.innerHTML=''); source.innerHTML='';
    const items=allEntries(key), map=read(key), placed=new Set();
    const tierEls=Object.fromEntries(tiers.map(t=>[t,panel.querySelector(`[data-drop-tier="${t}"]`)]));
    items.forEach(item=>{const stored=map[item.id]; const node=makeItem(item); if(stored && tierEls[stored]){tierEls[stored].append(node);placed.add(item.id)}else source.append(node)});
    bindDrag();
  }
  function bindDrag(){
    const zones=()=>[...panel.querySelectorAll('.tier-items'),source];
    const clearTargets=()=>zones().forEach(z=>z.classList.remove('is-pointer-target','is-dragover'));
    const zoneAt=(x,y)=>{
      const candidates=zones();
      for(const z of candidates){
        const r=z.getBoundingClientRect();
        if(x>=r.left && x<=r.right && y>=r.top && y<=r.bottom) return z;
      }
      return null;
    };
    panel.querySelectorAll('.rank-item').forEach(node=>{
      node.draggable=false;
      node.ondragstart=null; node.ondragend=null;
      node.onclick=()=>{
        if(node.dataset.pointerMoved==='1'){node.dataset.pointerMoved='0';return;}
        if(selectedRankItem===node){
          node.classList.remove('is-rank-selected');
          selectedRankItem=null;
        }else{
          panel.querySelectorAll('.rank-item.is-rank-selected').forEach(x=>x.classList.remove('is-rank-selected'));
          selectedRankItem=node;
          node.classList.add('is-rank-selected');
        }
      };
      let dragging=false,down=false,sx=0,sy=0,pid=null;
      const finish=(e,cancelled=false)=>{
        if(!down) return;
        down=false;
        clearTargets();
        try{if(pid!==null) node.releasePointerCapture(pid);}catch{}
        if(dragging && !cancelled){
          const z=zoneAt(e.clientX,e.clientY);
          if(z){moveNode(node,z);node.dataset.pointerMoved='1';}
          else node.dataset.pointerMoved='0';
        }
        node.classList.remove('is-pointer-dragging');
        dragging=false;pid=null;
      };
      node.onpointerdown=e=>{
        if(e.pointerType==='mouse' && e.button!==0)return;
        down=true;dragging=false;pid=e.pointerId;sx=e.clientX;sy=e.clientY;
        try{node.setPointerCapture(e.pointerId);}catch{}
      };
      node.onpointermove=e=>{
        if(!down || e.pointerId!==pid)return;
        const distance=Math.hypot(e.clientX-sx,e.clientY-sy);
        if(!dragging && distance>6){dragging=true;node.classList.add('is-pointer-dragging');}
        if(dragging){
          clearTargets();
          const z=zoneAt(e.clientX,e.clientY);
          if(z && z!==node.parentElement)z.classList.add('is-pointer-target');
          e.preventDefault();
        }
      };
      node.onpointerup=e=>finish(e,false);
      node.onpointercancel=e=>finish(e,true);
    });
  }
  function moveNode(node,zone){
    zone.append(node); const map=read(activeKey()); const id=node.dataset.rankId; let tier='source'; if(zone.dataset.dropTier) tier=zone.dataset.dropTier; map[id]=tier; write(activeKey(),map); node.dataset.moved='1';
  }
  panel.querySelectorAll('.tier-items').forEach(zone=>zone.addEventListener('click',e=>{
    if(!selectedRankItem) return;
    if(e.target.closest('.rank-item')) return;
    moveNode(selectedRankItem,zone);
    selectedRankItem.classList.remove('is-rank-selected');
    selectedRankItem=null;
  }));
  source.addEventListener('click',e=>{
    if(!selectedRankItem) return;
    if(e.target.closest('.rank-item')) return;
    moveNode(selectedRankItem,source);
    selectedRankItem.classList.remove('is-rank-selected');
    selectedRankItem=null;
  });
  tabs.forEach(tab=>tab.addEventListener('click',()=>{selectedRankItem=null;tabs.forEach(t=>{const on=t===tab;t.classList.toggle('is-active',on);t.setAttribute('aria-selected',String(on))});render(tab.dataset.ranking)}));
  document.getElementById('rankReset')?.addEventListener('click',()=>{if(confirm('Réinitialiser ce classement ?')){localStorage.removeItem(storageKey(activeKey()));render(activeKey())}});
  function roundedRectPath(ctx,x,y,w,h,r){
    r=Math.min(r,w/2,h/2);
    ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();
  }
  document.getElementById('rankExport')?.addEventListener('click',()=>{
    const key=activeKey();
    const title={partis:'Partis politiques',personnalites:'Personnalités politiques',rois:'Rois',medias:'Médias',presidents:'Présidents'}[key]||key;
    const W=2400,H=1600,canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;
    const ctx=canvas.getContext('2d');
    ctx.fillStyle='#07101d';ctx.fillRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#0c1727');bg.addColorStop(1,'#050a12');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#f5efe4';ctx.font='600 54px Georgia,serif';ctx.fillText('LYS — '+title,70,82);
    ctx.fillStyle='#9ca8b7';ctx.font='500 22px Arial,sans-serif';ctx.fillText('Classement personnel',72,118);
    const colors={S:'#2879d5',Superbe:'#47af62',Japprouve:'#e4c447',Indifferent:'#df8a35',Desapprouve:'#d84c4c',Impossible:'#7c4bd8',Inconnu:'#e49ad7'};
    const labels={S:'S',Superbe:'Superbe',Japprouve:"J’approuve",Indifferent:'Indifférent',Desapprouve:'Désapprouve',Impossible:'Impossible',Inconnu:'Inconnu'};
    const x0=60,y0=150,labelW=250,rowH=188,gap=10,totalW=W-120;
    const roundRect=(x,y,w,h,r)=>{ctx.beginPath();r=Math.min(r,w/2,h/2);ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();};
    for(let i=0;i<tiers.length;i++){
      const tier=tiers[i],y=y0+i*(rowH+gap);ctx.fillStyle='rgba(255,255,255,.035)';roundRect(x0,y,totalW,rowH,18);ctx.fill();
      ctx.fillStyle=colors[tier];roundRect(x0,y,labelW,rowH,18);ctx.fill();ctx.fillRect(x0+labelW-10,y,10,rowH);
      ctx.fillStyle=(tier==='Desapprouve'||tier==='Impossible')?'#fff':'#09101a';ctx.font='700 27px Arial,sans-serif';ctx.fillText(labels[tier],x0+22,y+48);
      ctx.fillStyle='rgba(255,255,255,.10)';ctx.fillRect(x0+labelW,y,totalW-labelW,rowH);
      let x=x0+labelW+18,yy=y+16;
      panel.querySelector(`.tier-items[data-drop-tier="${tier}"]`)?.querySelectorAll('.rank-item').forEach(node=>{
        const cardW=170,cardH=145;if(x+cardW>W-58){x=x0+labelW+18;yy+=cardH+12;}
        ctx.fillStyle='rgba(4,9,17,.78)';roundRect(x,yy,cardW,cardH,16);ctx.fill();
        const img=node.querySelector('img');
        const src=img?.currentSrc||img?.src||'';
        let imageDrawn=false;
        if(img?.complete && img.naturalWidth){
          try{
            const u=new URL(src,location.href);
            if(u.origin===location.origin){
              const boxW=110,boxH=82,ratio=Math.min(boxW/img.naturalWidth,boxH/img.naturalHeight),iw=img.naturalWidth*ratio,ih=img.naturalHeight*ratio;
              ctx.drawImage(img,x+30+(boxW-iw)/2,yy+8+(boxH-ih)/2,iw,ih); imageDrawn=true;
            }
          }catch(e){}
        }
        if(!imageDrawn){
          const nameForInitial=node.querySelector('.rank-item-name')?.textContent?.trim()||node.textContent.trim();
          const initial=(nameForInitial.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/)||['?'])[0].toUpperCase();
          ctx.fillStyle='rgba(181,138,75,.16)';roundRect(x+30,yy+8,110,82,14);ctx.fill();
          ctx.fillStyle='#d8b77a';ctx.font='600 38px Georgia,serif';ctx.textAlign='center';ctx.fillText(initial,x+85,yy+61);ctx.textAlign='start';
        }
        ctx.fillStyle='#eef2f6';ctx.font='700 15px Arial,sans-serif';const name=node.querySelector('.rank-item-name')?.textContent?.trim()||node.textContent.trim();ctx.fillText(name.length>20?name.slice(0,19)+'…':name,x+10,yy+112);
        ctx.fillStyle='#9aa6b5';ctx.font='500 10px Arial,sans-serif';ctx.fillText((node.querySelector('.rank-item-type')?.textContent||'').slice(0,26),x+10,yy+130);x+=cardW+10;
      });
    }
    let dataUrl;try{dataUrl=canvas.toDataURL('image/png');}catch(e){alert('Impossible de générer le PNG sur ce navigateur. Réessayez après le chargement complet des épingles.');return;}
    const a=document.createElement('a');a.href=dataUrl;a.download=`LYS-classement-${key}.png`;a.style.display='none';document.body.appendChild(a);a.click();a.remove();
  });

  let deferredPrompt=null; window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;const btn=document.getElementById('rankInstall');if(btn){btn.hidden=false;btn.onclick=async()=>{deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;btn.hidden=true}}});
  if('serviceWorker' in navigator) window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
  extract('partis');render('partis');
})();


/* Classements V2 — contrôleur de classement par clic, indépendant du drag. */
(function hardenRankingClickController(){
  const root=document.getElementById('classements');
  if(!root || root.dataset.clickControllerV2) return;
  root.dataset.clickControllerV2='1';
  const quick=root.querySelector('#rankingQuickMove');
  const quickName=root.querySelector('#rankingQuickName');
  let selected=null;
  const tiers=['S','Superbe','Japprouve','Indifferent','Desapprouve','Impossible','Inconnu'];
  const activeKey=()=>root.querySelector('.rank-tab.is-active')?.dataset.ranking || 'partis';
  const mapKey=k=>'lys-ranking-'+k;
  const readMap=k=>{try{return JSON.parse(localStorage.getItem(mapKey(k))||'{}')}catch{return {}}};
  const saveMap=(k,m)=>{try{localStorage.setItem(mapKey(k),JSON.stringify(m))}catch{}};
  const hideQuick=()=>{
    selected?.classList.remove('is-rank-selected');
    selected=null;
    if(quick) quick.hidden=true;
  };
  const move=(node,tier)=>{
    const zone=root.querySelector(`.tier-items[data-drop-tier="${tier}"]`);
    if(!zone || !node) return;
    zone.appendChild(node);
    const m=readMap(activeKey()); m[node.dataset.rankId]=tier; saveMap(activeKey(),m);
    node.classList.remove('is-rank-selected');
    node.dataset.moved='1';
    hideQuick();
  };
  // Capture phase guarantees selection works even if older handlers stop propagation.
  root.addEventListener('click',e=>{
    const item=e.target.closest('.rank-item');
    if(item){
      e.preventDefault(); e.stopPropagation();
      if(selected===item){hideQuick();return;}
      selected?.classList.remove('is-rank-selected');
      selected=item; item.classList.add('is-rank-selected');
      if(quick){quick.hidden=false; if(quickName) quickName.textContent=`Classer : ${item.title.split(' — ')[0]}`;}
      return;
    }
    const button=e.target.closest('[data-quick-tier]');
    if(button && selected){e.preventDefault();e.stopPropagation();move(selected,button.dataset.quickTier);return;}
    const zone=e.target.closest('.tier-items');
    if(zone && selected){const tier=zone.dataset.dropTier;if(tier){e.preventDefault();e.stopPropagation();move(selected,tier);}}
  },true);
  quick?.addEventListener('click',e=>{
    const b=e.target.closest('[data-quick-tier]'); if(b&&selected) move(selected,b.dataset.quickTier);
  });
})();

/* V18 — personnalités ajoutées : même fiche visuelle que les autres personnalités politiques. */
Object.assign(POLITIQUES, {
  "Dieudonné M'Bala M'Bala": {
    type:"Politique · Personnalité publique et candidat",
    dates:"Engagement électoral depuis 1997 · France Libre en 2024",
    parties:"France Libre : tête de liste Francis Lalanne aux européennes 2024, Dieudonné en 3e position ; candidature législative en Guadeloupe en 2024",
    history:"Dieudonné M'Bala M'Bala est d'abord devenu célèbre comme humoriste et acteur, notamment dans le duo formé avec Élie Semoun. À partir des années 2000, son activité publique se politise fortement. Il multiplie les candidatures électorales et construit un discours souverainiste, anti-système et très critique des institutions politiques et médiatiques. Aux européennes de 2024, il figure sur la liste France Libre conduite par Francis Lalanne, puis se présente aux législatives en Guadeloupe. Il n'a jamais exercé de mandat électif.",
    achievements:"Carrière d'humoriste, acteur et producteur; nombreuses candidatures électorales; participation à France Libre; présence durable dans le débat public sur la liberté d'expression, la souveraineté et les institutions.",
    deepDescriptionHtml:`<section class="bio-section"><h4>Parcours artistique et entrée en politique</h4><p>Après le succès du duo avec Élie Semoun, Dieudonné développe une carrière solo qui devient progressivement très politique. Ses spectacles, prises de parole et campagnes électorales l'installent dans un espace protestataire situé en marge des partis traditionnels.</p><p>Il a été candidat à plusieurs élections avant de rejoindre, en 2024, la liste <strong>France Libre</strong> menée par Francis Lalanne. Le ministère de l'Intérieur confirme sa présence en troisième position sur cette liste aux européennes du 9 juin 2024. Il est ensuite candidat aux législatives en Guadeloupe.</p></section><section class="bio-section"><h4>France Libre</h4><p>France Libre a été une <strong>liste de candidature aux européennes de 2024</strong>, portée par Francis Lalanne et dans laquelle Dieudonné figurait en troisième position. Le programme mettait notamment en avant la souveraineté nationale, la critique de l'Union européenne et la sortie de certaines structures supranationales. Le mouvement ne doit pas être confondu avec un parti parlementaire classique disposant d'un groupe élu à l'Assemblée nationale ou au Parlement européen.</p></section><section class="bio-section"><h4>Justice et controverses</h4><p>Son parcours comporte plusieurs condamnations et décisions administratives liées à des propos ou spectacles, ainsi qu'une condamnation financière pour fraude fiscale, blanchiment et abus de biens sociaux. Les juridictions ont notamment sanctionné certains propos en retenant des infractions précises ; cette distinction est importante pour ne pas confondre débat satirique, controverse politique et condamnation judiciaire.</p></section><section class="bio-section"><h4>Vie familiale</h4><p>Les informations publiques indiquent un premier mariage avec Marine Lutinier, avec qui il a eu quatre enfants, puis une relation avec Noémie Montagne, qui a également été sa productrice. Plusieurs sources rapportent un mariage avec Noémie Montagne en 2012 et plusieurs enfants. Le décompte global n'est pas suffisamment homogène entre les sources publiques pour être présenté ici comme un chiffre certain.</p></section><section class="bio-section"><h4>Liberté d'expression</h4><p>Son cas est souvent utilisé dans le débat sur les limites de la liberté d'expression. La jurisprudence française distingue la satire et la provocation artistique, d'une part, et les propos susceptibles de relever d'infractions de haine ou de contestation de crimes contre l'humanité, d'autre part.</p></section>`,
    portrait:"assets/politique/dieudonne-mbala-mbala.jpg"
  },
  "Francis Lalanne": {
    type:"Politique · Personnalité publique et candidat",
    dates:"Engagement électoral depuis 2007 · France Libre · candidature 2027 revendiquée",
    parties:"France Libre : tête de liste aux européennes 2024 ; actuellement présenté comme candidat présidentiel 2027 par sa structure de campagne",
    history:"Francis Lalanne est chanteur, auteur-compositeur, acteur et poète. Son engagement politique s'installe progressivement à partir des années 2000, avec plusieurs candidatures et alliances. Il devient une figure médiatique du mouvement des Gilets jaunes, conduit Alliance jaune aux européennes de 2019, puis mène la liste France Libre aux européennes de 2024 aux côtés de Dieudonné. En 2026, son site de campagne présente une candidature présidentielle pour 2027 sous la bannière « Lalanne 2027 — Pour une France Libre ».",
    achievements:"Longue carrière musicale; candidatures législatives et européennes; Alliance jaune; France Libre; prises de position sur les libertés, la souveraineté et les institutions; campagne présidentielle annoncée pour 2027.",
    deepDescriptionHtml:`<section class="bio-section"><h4>Du spectacle à la politique</h4><p>La carrière artistique de Francis Lalanne précède largement son engagement électoral. Il se présente aux législatives dès 2007, participe ensuite à plusieurs dynamiques politiques et devient l'une des figures médiatiques des Gilets jaunes. En 2019, il conduit la liste Alliance jaune aux européennes.</p></section><section class="bio-section"><h4>France Libre</h4><p>En 2024, Francis Lalanne conduit la liste <strong>France Libre</strong> aux élections européennes. Le ministère de l'Intérieur le donne comme tête de liste et Dieudonné en troisième position. La plateforme mettait en avant la souveraineté, la critique de l'Union européenne et un renouvellement institutionnel. En 2026, Lalanne se présente également sur son site de campagne comme candidat à l'élection présidentielle de 2027, sous une bannière « France Libre ».</p></section><section class="bio-section"><h4>Justice, inéligibilité et controverses</h4><p>Francis Lalanne a fait l'objet de plusieurs procédures et condamnations. En 2025, le Conseil d'État l'a déclaré inéligible pendant 18 mois pour des manquements relatifs au compte de campagne des européennes de 2024. D'autres procédures ont concerné des conflits avec des proches. Ses prises de position pendant la crise sanitaire et sur la guerre en Ukraine ont également suscité de fortes controverses publiques.</p></section><section class="bio-section"><h4>Vie familiale</h4><p>Francis Lalanne a été marié à Stella Sulak pendant environ quinze ans et ils ont eu quatre enfants. Il a ensuite eu une relation avec Alice Poussin, avec laquelle il a eu une fille. Les informations privées sont limitées ici aux éléments publiquement documentés.</p></section><section class="bio-section"><h4>Positionnement</h4><p>Sa trajectoire mélange culture populaire, écologie, critique des institutions, souverainisme et discours de défiance envers certains pouvoirs publics. Le profil est donc plus transversal qu'une appartenance durable à un parti traditionnel.</p></section>`,
    portrait:"assets/politique/francis-lalanne.webp"
  },
  "Patrick Sébastien": {
    type:"Politique · Personnalité publique et fondateur de mouvement",
    dates:"Mouvement citoyen « Ça suffit » lancé fin 2025 · objectif affiché : peser sur 2027",
    parties:"Ça suffit · mouvement citoyen, distinct d'un parti parlementaire traditionnel",
    history:"Patrick Sébastien est animateur, humoriste, imitateur, producteur et chanteur. Après une longue carrière dans le spectacle et la télévision, il lance fin 2025 le mouvement citoyen « Ça suffit » afin de porter des revendications et de peser sur l'élection présidentielle de 2027. Sa démarche se situe volontairement à distance des partis traditionnels et s'appuie sur un registre de parole populaire, festif et anti-professionnels de la politique.",
    achievements:"Longue carrière télévisuelle et musicale; création du mouvement « Ça suffit »; prises de position sur la vie publique, l'euthanasie, les services publics et la représentation politique; démarche visant 2027.",
    deepDescriptionHtml:`<section class="bio-section"><h4>Une longue carrière avant la politique</h4><p>Patrick Sébastien s'est imposé comme animateur, humoriste et producteur à la télévision et dans le spectacle. Son image publique repose sur la fête populaire, l'imitation, la proximité avec le public et un discours régulièrement critique envers les élites médiatiques et politiques.</p></section><section class="bio-section"><h4>Le mouvement « Ça suffit »</h4><p>Fin 2025, il lance <strong>Ça suffit</strong>, un mouvement citoyen destiné à faire remonter les revendications de la population et à peser sur la présidentielle de 2027. Son propre site appelle à rejoindre le mouvement. Le mouvement ne se présente pas comme un parti classique ; il cherche plutôt à créer un véhicule de mobilisation citoyenne.</p><p>Une analyse publiée par <em>Le Monde</em> en janvier 2026 décrit cette initiative comme une forme de « dégagisme festif » et comme une mutation du registre populiste : moins fondée sur l'ingénierie numérique que sur la proximité, les émotions et une mise en scène artisanale de la parole citoyenne.</p></section><section class="bio-section"><h4>Vie familiale</h4><p>Patrick Sébastien a eu plusieurs unions et plusieurs enfants. Il a été marié notamment à Martine, Sylvie, Fanfan puis Nathalie Boutot, dite Nana. Les sources biographiques rapportent plusieurs enfants, dont Sébastien, Olivier, Benjamin et Lily, adoptée en 2007 avec Nathalie Boutot. Son fils Sébastien est mort dans un accident de moto ; une petite-fille, Marie-Andréa, est née quelques mois plus tard.</p></section><section class="bio-section"><h4>Débat et controverse</h4><p>Son entrée en politique repose moins sur une doctrine partisane stable que sur une critique du fonctionnement de la représentation politique et sur la volonté de parler directement aux catégories populaires. Ses prises de position sur la peine de mort, l'insécurité, l'immigration ou les institutions ont suscité des débats et des critiques, tandis que ses partisans y voient une parole plus directe et moins codifiée.</p></section>`,
    portrait:"assets/politique/patrick-sebastien.webp"
  },
  "Caroline Galactéros": {
    type:"Politique · Géopolitologue et analyste stratégique",
    dates:"Docteure en sciences politiques · présidente de GéoPragma · analyse stratégique",
    parties:"Engagement ponctuel comme conseillère diplomatique d'Éric Zemmour en 2022 ; activité principale hors parti",
    history:"Caroline Galactéros est une géopolitologue, docteure en sciences politiques, essayiste et analyste stratégique. Officière supérieure de réserve, elle a travaillé sur les questions de défense, de stratégie et de négociation de crise. Elle préside aujourd'hui le think tank GéoPragma. Son approche se veut centrée sur les rapports de puissance, les intérêts nationaux, la souveraineté et le dialogue entre États, avec une lecture souvent critique des grilles occidentales dominantes sur les conflits internationaux.",
    achievements:"Doctorat en sciences politiques; enseignement et travaux en stratégie; parcours dans l'environnement de défense; fondation et présidence de GéoPragma; nombreuses interventions sur la Russie, l'Ukraine, l'Europe, l'OTAN, les États-Unis et la multipolarité.",
    deepDescriptionHtml:`<section class="bio-section"><h4>Formation et parcours stratégique</h4><p>Caroline Galactéros est docteure en sciences politiques et a travaillé sur la stratégie, la négociation de crise et les relations internationales. Des sources de présentation de son parcours indiquent des fonctions d'enseignement à HEC et à l'École de guerre ainsi qu'un parcours d'officier supérieur de réserve. Elle fonde et préside le think tank GéoPragma.</p></section><section class="bio-section"><h4>Une lecture moins conventionnelle des conflits</h4><p>Son approche s'écarte volontairement des lectures manichéennes « bloc contre bloc ». Elle met l'accent sur les intérêts des États, la souveraineté, les rapports de puissance, la profondeur historique et la nécessité de conserver des canaux diplomatiques. Dans ses textes et entretiens, elle défend notamment l'idée que la France devrait retrouver davantage de marge stratégique et dialoguer avec des puissances comme la Russie ou la Chine plutôt que de raisonner uniquement dans un cadre atlantique.</p><p>Cette approche est revendiquée par GéoPragma comme une méthode d'analyse indépendante des alignements politiques. Le think tank affirme qu'il ne se place ni dans une allégeance à Moscou ni dans une allégeance à Washington et cherche à analyser les États selon leurs intérêts et leurs rapports de force.</p></section><section class="bio-section"><h4>Russie, Ukraine et débat public</h4><p>Depuis la guerre en Ukraine, ses positions sont devenues particulièrement visibles et controversées. Elle critique certaines orientations occidentales, insiste sur les intérêts russes, les effets de l'élargissement de l'OTAN et les risques d'escalade, et plaide régulièrement pour la négociation. Des critiques extérieures la décrivent au contraire comme trop favorable à la lecture russe du conflit ou comme relayant certains récits pro-Kremlin. La fiche présente ces deux lectures afin de distinguer son approche revendiquée de la manière dont elle est contestée dans le débat public.</p></section><section class="bio-section"><h4>Passage auprès d'Éric Zemmour</h4><p>Après la présidentielle de 2022, GéoPragma indique que son engagement auprès d'Éric Zemmour a été ponctuel et bénévole, et qu'elle a ensuite repris une activité d'analyse indépendante sans allégeance partisane. Son passage dans cette équipe ne constitue donc pas, à lui seul, l'appartenance à un parti.</p></section>`,
    portrait:"assets/politique/caroline-galacteros.jpg"
  }
});
for (const [name, d] of Object.entries(POLITIQUES)) D[name] = d;


