function openRebuiltFourProfile(name){
  const d=REBUILT_FOUR_PROFILES[name], modal=document.getElementById('modal'), reader=document.getElementById('reader');
  if(!d||!modal||!reader)return;
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const sourceRows=d.sources.map(x=>`<a class="political-source-item" href="${esc(x[1])}" target="_blank" rel="noreferrer"><span>↗</span><strong>${esc(x[0])}</strong></a>`).join('');
  const cards=[['Présentation',d.presentation],['Repères chronologiques',d.chronology],['Règne et décisions',d.decisions],['Pouvoir et société',d.power],['Famille et alliances',d.family],['Contexte historique',d.context],['Héritage et mémoire',d.legacy]].map((x,i)=>`<section class="profile-card ${i===0?'profile-card-wide':''}"><div class="profile-card-kicker">${x[0].toUpperCase()}</div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></section>`).join('');
  reader.innerHTML=`<div class="reader-hero reader-political rebuilt-political-reader"><div class="reader-visual"><div class="reader-portraits"><img class="portrait" src="${esc(d.portrait)}" alt="Portrait de ${esc(d.title)}"></div><div class="reader-portrait-caption">${esc(d.type)}</div></div><div class="reader-intro"><span class="reader-eyebrow">FICHE ENCYCLOPÉDIQUE</span><h2>${esc(d.title)}</h2><p class="reader-lead">${esc(d.role)}</p><div class="reader-facts"><div class="reader-fact"><span>DATE DE NAISSANCE</span><strong>${esc(d.birth)}</strong></div><div class="reader-fact"><span>DATE DE DÉCÈS</span><strong>${esc(d.death)}</strong></div><div class="reader-fact"><span>PARTI / COURANT</span><strong>${esc(d.parties)}</strong></div></div></div></div><div class="reader-body political-unified-sheet"><div class="political-profile-grid">${cards}</div><section class="political-sources"><div class="political-sources-head"><span class="section-kicker">SOURCES</span><h3>Sources et méthode</h3><p>Références institutionnelles et sources documentaires utilisées pour établir cette fiche.</p></div><div class="political-sources-grid">${sourceRows}</div></section></div>`;
  modal.hidden=false;modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
}
(function(){
  const original=window.openTopic;
  if(typeof original==='function'){
    window.openTopic=function(name){if(REBUILT_FOUR_PROFILES[name]) return openRebuiltFourProfile(name); return original(name)};
  }
})();


/* Wikimedia Commons — images de monuments avec conservation de la provenance et de la licence. */
(function initMonumentImageSearch(){
  const boxes=[...document.querySelectorAll('.monument-card-image[data-wikimedia-query]')];
  if(!boxes.length)return;
  const cacheKey=q=>'lys-monument-image-v2:'+q.toLocaleLowerCase('fr-FR');
  const readCache=q=>{try{return JSON.parse(localStorage.getItem(cacheKey(q))||'null')}catch{return null}};
  const writeCache=(q,value)=>{try{localStorage.setItem(cacheKey(q),JSON.stringify(value))}catch{}}
  const search=async q=>{
    const cached=readCache(q);if(cached?.src)return cached;
    const url='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(q)+'&gsrnamespace=6&gsrlimit=1&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=1200&format=json&origin=*';
    try{
      const response=await fetch(url,{mode:'cors'});if(!response.ok)return null;
      const json=await response.json();const page=Object.values(json.query?.pages||{})[0];const info=page?.imageinfo?.[0];
      if(!info)return null;
      const value={src:info.thumburl||info.url||'',descriptionurl:info.descriptionurl||'',license:info.extmetadata?.LicenseShortName?.value||'',artist:info.extmetadata?.Artist?.value||''};
      if(value.src)writeCache(q,value);return value.src?value:null;
    }catch{return null;}
  };
  window.LYS_LOOKUP_MONUMENT_IMAGE=search;
  const load=async box=>{
    const q=box.dataset.wikimediaQuery,img=box.querySelector('.monument-remote-image');if(!q||!img)return;
    const result=await search(q);
    if(result?.src){img.src=result.src;img.dataset.sourceUrl=result.descriptionurl||'';img.dataset.license=result.license||'';img.dataset.artist=result.artist||'';img.addEventListener('error',()=>box.classList.add('is-image-failed'),{once:true});}
    else box.classList.add('is-image-failed');
  };
  let index=0;const runBatch=()=>{const batch=boxes.slice(index,index+8);index+=8;if(!batch.length)return;Promise.all(batch.map(load)).finally(()=>setTimeout(runBatch,80));};runBatch();
})();

