/* Lightbox portfolio — gestion directe et robuste du clic. */
(function initPierrefondsPortfolioLightbox(){
 const lb=document.getElementById('portfolioLightbox'), img=document.getElementById('portfolioLightboxImage'), cap=document.getElementById('portfolioLightboxCaption');
 if(!lb||!img)return;
 const close=()=>{lb.hidden=true;lb.setAttribute('aria-hidden','true');document.body.style.overflow='';img.removeAttribute('src');};
 const open=src=>{if(!src)return;img.src=src.getAttribute('src')||src.currentSrc||'';img.alt=src.alt||'';if(cap)cap.textContent=(src.alt||'').replace(/^Affiche\s+/,'');lb.hidden=false;lb.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';};
 document.addEventListener('click',e=>{const btn=e.target.closest('.portfolio-zoom');if(btn){e.preventDefault();e.stopPropagation();open(btn.querySelector('img'));return;}if(e.target===lb||e.target.closest('.portfolio-lightbox-close'))close();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!lb.hidden)close();});
})();

