/* V128.1 — accueil : ancrage explicite à la fenêtre, indépendamment des conteneurs parents. */
(function forceHomeViewport(){
  const apply=()=>{
    const hero=document.getElementById('accueil');
    const gallery=document.getElementById('heroGallery');
    if(!hero||!gallery) return;
    const set=(el,styles)=>Object.entries(styles).forEach(([k,v])=>el.style.setProperty(k,v,'important'));
    set(hero,{
      position:'relative',width:'100vw',maxWidth:'100vw',left:'50%',marginLeft:'0',marginRight:'0',transform:'translateX(-50%)',padding:'0',overflow:'hidden'
    });
    set(gallery,{position:'absolute',left:'0',right:'0',top:'0',bottom:'0',width:'100vw',maxWidth:'100vw',height:'100%',margin:'0',transform:'none',overflow:'hidden'});
    gallery.querySelectorAll('.hero-slide').forEach(slide=>{
      set(slide,{position:'absolute',left:'0',right:'0',top:'0',bottom:'0',width:'100%',height:'100%',margin:'0',padding:'0'});
      const img=slide.querySelector('img');
      if(img) set(img,{position:'absolute',left:'0',right:'0',top:'0',bottom:'0',width:'100%',height:'100%',maxWidth:'none',maxHeight:'none',objectFit:'cover',objectPosition:'center center',transform:'none'});
    });
  };
  apply();
  window.addEventListener('resize',apply,{passive:true});
  window.addEventListener('orientationchange',apply,{passive:true});
  setTimeout(apply,100); setTimeout(apply,500);
})();

